window.CC.p.push({n:11,view:"<section class=\"view\" id=\"p11\" hidden style=\"--c:#a23fb5\"><h1><i>11</i>Dermatology</h1><p class=\"lead\">30 sections — pick what you want to read.</p><div class=\"grid\"><h3 class=\"sg\">Part 11A</h3><div class=\"card\" data-u=\"u263\"><button class=\"open\" data-u=\"u263\"><b>Case 1</b><span>Acne Vulgaris &amp; Rosacea</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acne+Vulgaris+%26+Rosacea\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u264\"><button class=\"open\" data-u=\"u264\"><b>Case 2</b><span>Atopic Dermatitis (ECZEMA)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Atopic+Dermatitis+%28ECZEMA%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u265\"><button class=\"open\" data-u=\"u265\"><b>Case 3</b><span>Contact Dermatitis &amp; Seborrheic Dermatitis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Contact+Dermatitis+%26+Seborrheic+Dermatitis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u266\"><button class=\"open\" data-u=\"u266\"><b>Case 4</b><span>Psoriasis Vulgaris</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Psoriasis+Vulgaris\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u267\"><button class=\"open\" data-u=\"u267\"><b>Case 5</b><span>Lichen Planus &amp; Pityriasis Rosea</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Lichen+Planus+%26+Pityriasis+Rosea\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u268\"><button class=\"open\" data-u=\"u268\"><b>Case 6</b><span>Urticaria (HIVES) &amp; Angioedema</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Urticaria+%28HIVES%29+%26+Angioedema\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u269\"><button class=\"open\" data-u=\"u269\"><b>Case 7</b><span>Impetigo, Ecthyma &amp; Folliculitis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Impetigo%2C+Ecthyma+%26+Folliculitis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u270\"><button class=\"open\" data-u=\"u270\"><b>Case 8</b><span>Herpes Simplex Virus (HSV-1 &amp; HSV-2) &amp; Eczema Herpeticum</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Herpes+Simplex+Virus+%28HSV-1+%26+HSV-2%29+%26+Eczema+Herpeticum\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u271\"><button class=\"open\" data-u=\"u271\"><b>Case 9</b><span>Herpes Zoster (SHINGLES) &amp; Postherpetic Neuralgia (PHN)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Herpes+Zoster+%28SHINGLES%29+%26+Postherpetic+Neuralgia+%28PHN%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u272\"><button class=\"open\" data-u=\"u272\"><b>Case 10</b><span>Viral Warts (VERRUCAE) &amp; Molluscum Contagiosum</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Viral+Warts+%28VERRUCAE%29+%26+Molluscum+Contagiosum\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u273\"><button class=\"open\" data-u=\"u273\"><b>Case 11</b><span>Dermatophytosis (SUPERFICIAL FUNGAL &quot;TINEA&quot; INFECTIONS)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Dermatophytosis+%28SUPERFICIAL+FUNGAL+%22TINEA%22+INFECTIONS%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u274\"><button class=\"open\" data-u=\"u274\"><b>Case 12</b><span>Tinea Versicolor &amp; Cutaneous Candidiasis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Tinea+Versicolor+%26+Cutaneous+Candidiasis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u275\"><button class=\"open\" data-u=\"u275\"><b>Case 13</b><span>Scabies (SARCOPTES SCABIEI)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Scabies+%28SARCOPTES+SCABIEI%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u276\"><button class=\"open\" data-u=\"u276\"><b>Case 14</b><span>Pediculosis (LICE) &amp; Cutaneous Leishmaniasis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pediculosis+%28LICE%29+%26+Cutaneous+Leishmaniasis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u277\"><button class=\"open\" data-u=\"u277\"><b>Case 15</b><span>Erythema Multiforme (EM) vs. SJS / TEN (DERMATOLOGIC EMERGENCY!)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Erythema+Multiforme+%28EM%29+vs.+SJS+%2F+TEN+%28DERMATOLOGIC+EMERGENCY%21%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><h3 class=\"sg\">Part 11B</h3><div class=\"card\" data-u=\"u278\"><button class=\"open\" data-u=\"u278\"><b>Case 16</b><span>Pemphigus Vulgaris vs. Bullous Pemphigoid</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pemphigus+Vulgaris+vs.+Bullous+Pemphigoid\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u279\"><button class=\"open\" data-u=\"u279\"><b>Case 17</b><span>Vitiligo &amp; Melasma</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Vitiligo+%26+Melasma\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u280\"><button class=\"open\" data-u=\"u280\"><b>Case 18</b><span>Alopecia Areata, Androgenetic Alopecia &amp; Telogen Effluvium</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Alopecia+Areata%2C+Androgenetic+Alopecia+%26+Telogen+Effluvium\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u281\"><button class=\"open\" data-u=\"u281\"><b>Case 19</b><span>Erythema Nodosum &amp; Pyoderma Gangrenosum</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Erythema+Nodosum+%26+Pyoderma+Gangrenosum\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u282\"><button class=\"open\" data-u=\"u282\"><b>Case 20</b><span>Cutaneous Lupus Erythematosus &amp; Dermatomyositis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Cutaneous+Lupus+Erythematosus+%26+Dermatomyositis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u283\"><button class=\"open\" data-u=\"u283\"><b>Case 21</b><span>Leukocytoclastic Vasculitis (APPROACH TO PALPABLE PURPURA)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Leukocytoclastic+Vasculitis+%28APPROACH+TO+PALPABLE+PURPURA%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u284\"><button class=\"open\" data-u=\"u284\"><b>Case 22</b><span>Drug Eruptions (MORBILLIFORM, FIXED DRUG ERUPTION &amp; DRESS SYNDROME)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Drug+Eruptions+%28MORBILLIFORM%2C+FIXED+DRUG+ERUPTION+%26+DRESS+SYNDROME%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u285\"><button class=\"open\" data-u=\"u285\"><b>Case 23</b><span>Pityriasis Alba, Keratosis Pilaris &amp; Xerosis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pityriasis+Alba%2C+Keratosis+Pilaris+%26+Xerosis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u286\"><button class=\"open\" data-u=\"u286\"><b>Case 24</b><span>Hidradenitis Suppurativa (ACNE INVERSA)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Hidradenitis+Suppurativa+%28ACNE+INVERSA%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u287\"><button class=\"open\" data-u=\"u287\"><b>Case 25</b><span>Generalized Pruritus Without a Primary Rash (SYSTEMIC APPROACH!)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Generalized+Pruritus+Without+a+Primary+Rash+%28SYSTEMIC+APPROACH%21%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u288\"><button class=\"open\" data-u=\"u288\"><b>Case 26</b><span>Basal Cell Carcinoma (BCC)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Basal+Cell+Carcinoma+%28BCC%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u289\"><button class=\"open\" data-u=\"u289\"><b>Case 27</b><span>Squamous Cell Carcinoma (SCC) &amp; Actinic Keratosis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Squamous+Cell+Carcinoma+%28SCC%29+%26+Actinic+Keratosis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u290\"><button class=\"open\" data-u=\"u290\"><b>Case 28</b><span>Malignant Melanoma (ABCDEs &amp; BRESLOW DEPTH)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Malignant+Melanoma+%28ABCDEs+%26+BRESLOW+DEPTH%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u291\"><button class=\"open\" data-u=\"u291\"><b>Case 29</b><span>Benign Skin Tumors &amp; Keloids vs. Hypertrophic Scars</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Benign+Skin+Tumors+%26+Keloids+vs.+Hypertrophic+Scars\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u292\"><button class=\"open\" data-u=\"u292\"><b>Case 30</b><span>Cutaneous Markers of Internal Disease</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Cutaneous+Markers+of+Internal+Disease\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div></div></section>",units:"<article class=\"view unit\" id=\"u263\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 1</span><h1>Acne Vulgaris &amp; Rosacea</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acne+Vulgaris+%26+Rosacea\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><ul>\n<li class=\"l1\"><b>Acne Vulgaris:</b> Chronic inflammatory disorder of the <b>pilosebaceous unit</b> affecting adolescents and young adults (face, chest, upper back).</li>\n<li class=\"l1\"><b>Rosacea:</b> Chronic inflammatory facial dermatosis of middle-aged adults (<b>30–50 years</b>, fair skin) affecting the <b>central face</b> (cheeks, nose, chin, forehead).</li>\n</ul><h3><b>2. Etiology &amp; Pathogenesis (Separated — 4 Pillars of Acne!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Follicular Hyperkeratinization:</b> Abnormal shedding of keratinocytes plugs the follicular orifice -&gt; <b>Comedones</b> (open = blackhead; closed = whitehead).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Androgen-Driven Sebum Hypersecretion:</b> Pubertal/PCOS androgens stimulate sebaceous glands.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Bacterial Colonization:</b> <i><b>Cutibacterium acnes</b></i><b> (formerly </b><i><b>Propionibacterium acnes</b></i><b>)</b> proliferates inside lipid-rich clogged follicles.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Inflammation:</b> <i>C. acnes</i> triggers <b>TLR-2</b> (Toll-Like Receptor 2) inflammation -&gt; papules, pustules, nodules, cysts, and scarring.</span></p>\n<ul>\n<li class=\"l1\"><i>Acne Aggravators:</i> <mark class=\"hl lab\"><b>PCOS</b></mark> (Polycystic Ovary Syndrome), Corticosteroids (\"steroid acne\"), Lithium, mechanical friction, high-glycemic diet/skim milk.</li>\n</ul><h3><b>3. Clinical Picture &amp; Differentiation (Acne vs. Rosacea)</b></h3><ul>\n<li class=\"l1\"><b>Acne Vulgaris:</b> Polymorphous lesions (<b>Comedones [PATHOGNOMONIC for Acne!]</b> + inflammatory papules, pustules, nodules, cysts) + post-inflammatory hyperpigmentation/scars.</li>\n<li class=\"l1\"><b>Rosacea:</b> <b>NO COMEDONES!</b> Features <b>flushing</b> (triggered by <b>sunlight, hot drinks, spicy food, alcohol, stress</b>), persistent central facial <b>erythema &amp; telangiectasias</b>, papules/pustules, <b>Rhinophyma</b> (bulbous nose), and <b>Ocular Rosacea</b> (blepharitis/conjunctivitis).</li>\n</ul><h3><b>4. Investigations &amp; DDx</b></h3><ul>\n<li class=\"l1\">Diagnosis is <b>Clinical</b>! <i>(Order </i><i><b>Free/Total Testosterone, DHEA-S, LH/FSH</b></i><i> ONLY if severe female acne + hirsutism/irregular menses -&gt; rule out </i><mark class=\"hl lab\"><i><b>PCOS</b></i></mark><i> or </i><i><b>CAH </b></i><i>[Congenital Adrenal Hyperplasia]!).</i></li>\n<li class=\"l1\"><b>DDx:</b> Rosacea, Perioral dermatitis (spares vermilion border, worsened by <b>topical steroids!</b>), Folliculitis, Drug-induced acne.</li>\n</ul><h3><b>5. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Acne Vulgaris (Stepwise Ladder — Takes 8–12 Weeks to Work!):</b></li>\n<li class=\"l2\"><i>Mild Comedonal:</i> <b>Topical Retinoid</b> (<b>Adapalene</b> or <b>Tretinoin</b> at night — <i>teratogenic, apply pea-sized amount, use sunscreen!</i>) +/- <b>Benzoyl Peroxide (BPO)</b> wash.</li>\n<li class=\"l2\"><i>Mild-Moderate Inflammatory:</i> <mark class=\"hl rx\"><b>Topical Retinoid + Benzoyl Peroxide + Topical Clindamycin/Erythromycin</b></mark> <i>(NEVER use topical antibiotics ALONE — prevents bacterial resistance! Always combine with BPO!)</i>.</li>\n<li class=\"l2\"><i>Moderate-Severe Inflammatory:</i> Add <b>Oral Antibiotic</b> (<mark class=\"hl rx\"><b> Doxycycline 100 mg OD/BID</b></mark> or Minocycline for max 3 months — <i>avoid in pregnancy &amp; children &lt; 8 yrs; warn about photosensitivity &amp; pill esophagitis!</i>) OR <b>COCs</b> (Combined Oral Contraceptives) / <mark class=\"hl rx\"><b>Spironolactone</b></mark> in females!</li>\n<li class=\"l2\"><i>Severe Nodulocystic / Scarring / Refractory Acne:</i> <b>Oral Isotretinoin</b> (13-cis-retinoic acid — <b>ONLY curative drug!</b>).</li>\n<li class=\"l1\"><mark class=\"hl dx\"><b>MANDATORY ISOTRETINOIN SAFETY RULES:</b></mark> <b>STRICTLY TERATOGENIC</b> (requires 2 negative pregnancy tests + <b>2 forms of contraception</b> 1 month before, during, and 1 month after!); monitor baseline/monthly <mark class=\"hl mech\"><b>LFTs</b></mark> (Liver Function Tests) &amp; <b>Fasting Triglycerides</b>; expect dry lips (<b>cheilitis</b>) and xerosis!</li>\n<li class=\"l1\"><b>Rosacea:</b> Daily broad-spectrum <b>Sunscreen</b> + avoid flushing triggers; <mark class=\"hl rx\"><b>Topical Metronidazole</b></mark> , <b>Azelaic Acid</b>, or <b>Ivermectin</b> cream (anti-Demodex) + <b>Topical Brimonidine</b> (for erythema); Oral <mark class=\"hl rx\"><b>Doxycycline</b></mark> (sub-antimicrobial 40 mg) for moderate-severe papulopustular/ocular rosacea!</li>\n</ul><nav class=\"un\"><span></span><button class=\"nv\" data-u=\"u264\">Case 2 →</button></nav></article><article class=\"view unit\" id=\"u264\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 2</span><h1>Atopic Dermatitis (ECZEMA)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Atopic+Dermatitis+%28ECZEMA%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Chronic, relapsing, <b>intensely pruritic</b> inflammatory skin disease characterized by epidermal barrier dysfunction (<b>\"The Itch That Rashes\"</b>). Part of the <b>\"Atopic Triad\"</b></p>\n<p>(<mark class=\"hl lab\"><b> Atopic Dermatitis + Allergic Rhinitis + Bronchial Asthma</b></mark> ).</p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Genetic Skin Barrier Defect:</b> Loss-of-function mutations in the <b>Filaggrin (</b><i><b>FLG</b></i><b>)</b> gene -&gt; defective stratum corneum -&gt; increased transepidermal water loss (<b>xerosis</b>) and allergen penetration.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Immune Dysregulation:</b> <b>Th2-skewed (IL-4, IL-13, IgE)</b> inflammatory response.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Environmental Triggers:</b> Dry winter weather, wool/synthetic fabrics, harsh soaps/fragrances, dust mites, sweat, stress, <i>Staphylococcus aureus</i> colonization.</span></p><h3><b>3. Clinical Picture (Changes With Age!)</b></h3><ul>\n<li class=\"l1\"><b>Infants (&lt; 2 Years):</b> Erythematous, oozing/crusted pruritic plaques on <b>CHEEKS, forehead, scalp, and extensor limbs</b> (<b>classically SPARES the diaper area!</b>).</li>\n<li class=\"l1\"><b>Children (2–12 Years) &amp; Adults:</b> Dry, scaly, <b>lichenified</b> (thickened leathery skin with accentuated skin markings from chronic scratching!) plaques in <b>FLEXURAL CREASES</b> (<b>antecubital and popliteal fossae</b>, wrists, ankles, neck!).</li>\n</ul><h3><b>4. Investigations &amp; Complications</b></h3><ul>\n<li class=\"l1\"><b>Diagnosis is Clinical</b> (elevated serum IgE is supportive, not required).</li>\n<li class=\"l1\"><b>Complications:</b></li>\n<li class=\"l2\">Secondary bacterial <b>Impetiginization</b> (<i>S. aureus</i> — golden honey-colored crusts!).</li>\n<li class=\"l2\"><b>Eczema Herpeticum (EMERGENCY!):</b> Sudden painful punched-out hemorrhagic vesicles/erosions + fever caused by <b>HSV-1</b> (Herpes Simplex Virus) spreading rapidly over eczematous skin -&gt; <mark class=\"hl rx\"><b>Immediate Oral/IV Acyclovir!</b></mark></li>\n</ul><h3><b>5. Treatment (\"Soak and Seal\" + Anti-Inflammatory!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Skin Barrier Repair (Cornerstone — Even When Clear!):</b> Thick, fragrance-free <b>Emollients / Ointments</b> (Petrolatum/Vaseline, Ceramide creams) applied <b>within 3 minutes after lukewarm bathing</b> (\"Soak &amp; Seal\"); mild soap-free cleansers; cotton clothing!</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Active Flare Control:</b></span></p>\n<ul>\n<li class=\"l2\"><mark class=\"hl rx\"><b>Topical Corticosteroids (TCS):</b></mark> Use <b>Low-Potency</b> (<mark class=\"hl rx\"><b> Hydrocortisone 1%</b></mark> ) on <b>face, groin, axillae, and infants</b>; <b>Medium-to-High Potency</b> (<mark class=\"hl rx\"><b> Mometasone, Betamethasone, Clobetasol</b></mark> ) on thick body plaques/lichenification for 1–2 weeks!</li>\n<li class=\"l2\"><b>Topical Calcineurin Inhibitors (TCIs — Steroid-Sparing!):</b> <mark class=\"hl rx\"><b>Tacrolimus</b></mark> or <b>Pimecrolimus</b> -&gt; ideal for <b>eyelids, face, and skin folds</b> (NO skin atrophy!).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Itch &amp; Infection:</b> Oral antihistamines (sedating Hydroxyzine at night helps sleep, though itch is mainly non-histamine!); treat superinfection with Mupirocin/Cephalexin.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Severe Refractory Disease:</b> Phototherapy (<b>NB-UVB</b>), <b>Dupilumab</b> (anti-IL-4Rα biologic — transformative!), or JAK inhibitors (Upadacitinib/Abrocitinib).</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u263\">← Case 1</button><button class=\"nv\" data-u=\"u265\">Case 3 →</button></nav></article><article class=\"view unit\" id=\"u265\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 3</span><h1>Contact Dermatitis &amp; Seborrheic Dermatitis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Contact+Dermatitis+%26+Seborrheic+Dermatitis\">🔍 Search on Google</a></header><h3><b>A. Contact Dermatitis (Irritant vs. Allergic)</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>Feature</b></p></th><th><p><b>Irritant Contact Dermatitis (~80%)</b></p></th><th><p><b>Allergic Contact Dermatitis (~20%)</b></p></th></tr><tr><td><p><b>Mechanism</b></p></td><td><p>Direct non-immune chemical/physical barrier damage (occurs in ANYONE if strong enough!)</p></td><td><p><b>Type IV (Delayed T-Cell) Hypersensitivity</b> (requires prior sensitization!)</p></td></tr><tr><td><p><b>Classic Triggers</b></p></td><td><p>Soaps, detergents, bleach, <b>wet work (housewives/dishwashers!)</b>, diaper urine/stool</p></td><td><p><b>Nickel</b> (watches, belt buckles, earrings — infraumbilical rash!), <b>Poison Ivy / Plants</b>, Fragrances, Latex, Hair dye (<mark class=\"hl lab\"><b> PPD</b></mark> ), Neomycin</p></td></tr><tr><td><p><b>Clinical &amp; Diagnosis</b></p></td><td><p>Dry, fissured, erythematous, burning plaques on <b>dorsal hands/fingers</b></p></td><td><p>Intensely pruritic, <b>geometric/linear erythematous vesicles &amp; oozing plaques</b> matching contact area; <b>Gold Standard = Patch Testing</b>!</p></td></tr><tr><td><p><b>Treatment</b></p></td><td><p>Avoid irritant + thick barrier emollients/gloves + <b>Topical Steroids</b></p></td><td><p>Strict allergen avoidance + <b>Mid/High-Potency Topical Steroids </b>(short <mark class=\"hl rx\"><b>Oral Prednisone taper 2–3 wks</b></mark> if severe/extensive/facial — <i>short 5-day packs rebound!</i>)</p></td></tr></table><h3><b>B. Seborrheic Dermatitis</b></h3><ul>\n<li class=\"l1\"><b>Etiology:</b> Inflammatory reaction to commensal lipophilic yeast <i><b>Malassezia furfur</b></i> in <b>sebum-rich areas</b> (worse in winter, stress, <b>Parkinson’s Disease</b>, and <b>severe HIV</b>!).</li>\n<li class=\"l1\"><b>Clinical Picture:</b> Greasy, yellowish scales on erythematous base affecting <b>Scalp (\"Dandruff\" / \"Cradle Cap\" in infants)</b>, <b>eyebrows, glabella, nasolabial folds, retroauricular creases, and central chest</b>.</li>\n<li class=\"l1\"><b>Treatment:</b></li>\n<li class=\"l2\"><i>Scalp:</i> <b>Ketoconazole 2%</b>, Selenium sulfide, or Zinc pyrithione <b>antifungal shampoos</b> (leave on scalp 5 min before rinsing!).</li>\n<li class=\"l2\"><i>Face/Body:</i> <b>Topical Ketoconazole 2% cream</b> + short course <mark class=\"hl rx\"><b>Low-potency Topical Steroid (Hydrocortisone 1%)</b></mark> or <mark class=\"hl rx\"><b>Tacrolimus/Pimecrolimus</b></mark> . <i>(Infants Cradle Cap: mineral/olive oil massage + gentle brushing + mild ketoconazole shampoo).</i></li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u264\">← Case 2</button><button class=\"nv\" data-u=\"u266\">Case 4 →</button></nav></article><article class=\"view unit\" id=\"u266\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 4</span><h1>Psoriasis Vulgaris</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Psoriasis+Vulgaris\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Chronic, immune-mediated (<b>Th1 / Th17 — TNF-α, IL-17, IL-23</b>) hyperproliferative inflammatory skin and systemic disease affecting ~2% of the population.</p><h3><b>2. Etiology &amp; Triggers (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Genetic Predisposition:</b> Strong polygenic link (<b>HLA-Cw6</b>).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Environmental / Systemic Triggers:</b></span></p>\n<ul>\n<li class=\"l2\"><b>Skin Trauma (Koebner Phenomenon):</b> New psoriatic plaques appear along surgical scars, scratches, or tattoos!</li>\n<li class=\"l2\"><b>Infections:</b> <b>GAS</b> (Group A <i>Streptococcus</i>) pharyngitis triggers <b>Guttate Psoriasis</b> (\"raindrop\" plaques in kids/young adults!).</li>\n<li class=\"l2\"><b>Medications (WORSEN Psoriasis!):</b> <b>Beta-blockers</b>, <b>Lithium</b>, Antimalarials, <b>Systemic Corticosteroid Withdrawal</b> (triggers <b>Generalized Pustular Psoriasis!</b>).</li>\n<li class=\"l2\"><b>Lifestyle:</b> Stress, smoking, obesity, alcohol.</li>\n</ul><h3><b>3. Clinical Picture (Classic Plaque Psoriasis ~80–90%)</b></h3><ul>\n<li class=\"l1\"><b>Well-demarcated erythematous plaques topped by thick, silvery-white micaceous scales</b> symmetrically over <mark class=\"hl lab\"><b>EXTENSOR surfaces</b></mark> (<b>Elbows, Knees</b>), scalp, and lower back/gluteal cleft!</li>\n<li class=\"l1\"><b>Auspitz Sign:</b> Pinpoint bleeding spots when silvery scale is gently scraped off!</li>\n<li class=\"l1\"><b>Nail Changes (~50%):</b> <b>\"Oil-drop\" (salmon patch) discoloration</b>, <b>nail pitting</b>, subungual hyperkeratosis, onycholysis (<b>strongly predicts Psoriatic Arthritis!</b>).</li>\n<li class=\"l1\"><b>Comorbidities:</b> <b>Psoriatic Arthritis (~20–30%)</b>, Metabolic Syndrome, Cardiovascular Disease, Depression!</li>\n</ul><h3><b>4. Differential Diagnosis (DDx)</b></h3><ul>\n<li class=\"l1\">Seborrheic dermatitis, Tinea corporis (check KOH!), Lichen planus, Secondary syphilis (check RPR!), Nummular eczema.</li>\n</ul><h3><b>5. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Localized / Mild (&lt; 5–10% BSA [Body Surface Area]):</b></li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>High-Potency Topical Corticosteroids</b></mark> (<mark class=\"hl rx\"><b> Clobetasol / Betamethasone</b></mark> ) combined with <b>Topical Vitamin D Analogues (Calcipotriene / Calcipotriol)</b> (synergistic &amp; reduces steroid atrophy!) +/- <b>Tazarotene</b> or Coal Tar / Salicylic acid (keratolytic for thick scales).</li>\n<li class=\"l1\"><b>Moderate-to-Severe (&gt; 10% BSA, Hands/Face/Genitals, or Psoriatic Arthritis):</b></li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>Phototherapy (NB-UVB — Narrowband Ultraviolet B)</b></mark> !</li>\n<li class=\"l2\"><b>Systemic Non-Biologics:</b> <mark class=\"hl rx\"><b>Methotrexate</b></mark> (also treats Psoriatic Arthritis — monitor LFTs/CBC, avoid in pregnancy/liver disease!), <b>Acitretin</b> (oral retinoid — 3-year pregnancy wait!), <mark class=\"hl rx\"><b>Cyclosporine</b></mark> (rapid control, nephrotoxic), <b>Apremilast</b>.</li>\n<li class=\"l2\"><b>Biologics (Highest Efficacy!):</b> <b>Anti-TNF (Adalimumab, Etanercept)</b>, <b>Anti-IL-17 (Secukinumab, Ixekizumab)</b>, <b>Anti-IL-23 (Guselkumab, Risankizumab)</b> — <i>ALWAYS screen for Latent </i><i><b>TB &amp; Hepatitis B</b></i><i> before starting!</i></li>\n<li class=\"l1\"><b>CRITICAL RULE:</b> <mark class=\"hl rx\"><b>NEVER prescribe Systemic Oral/IM Corticosteroids for Psoriasis</b></mark> -&gt; tapering triggers life-threatening <b>Generalized Pustular Psoriasis</b> or <b>Erythroderma</b>!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u265\">← Case 3</button><button class=\"nv\" data-u=\"u267\">Case 5 →</button></nav></article><article class=\"view unit\" id=\"u267\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 5</span><h1>Lichen Planus &amp; Pityriasis Rosea</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Lichen+Planus+%26+Pityriasis+Rosea\">🔍 Search on Google</a></header><h3><b>A. Lichen Planus (\"The 6 Ps\")</b></h3><ul>\n<li class=\"l1\"><b>Definition:</b> Idiopathic T-cell-mediated mucocutaneous inflammatory disorder (<b>strongly associated with Hepatitis C Virus [HCV] in Egypt!</b>).</li>\n<li class=\"l1\"><b>Clinical Picture — \"6 Ps\":</b> <b>P</b>ruritic, <b>P</b>urple (violaceous), <b>P</b>olygonal, <b>P</b>lanar (flat-topped) <b>P</b>apules and <b>P</b>laques on <b>flexor wrists, ankles, shins, and lower back</b>!</li>\n<li class=\"l1\"><b>Pathognomonic Features:</b> <b>Wickham’s Striae</b> (fine lacy white lines on surface of papules and <b>buccal mucosa</b>!), <b>Koebner phenomenon</b>, nail pterygium / scarring alopecia.</li>\n<li class=\"l1\"><b>Workup &amp; Treatment:</b> Screen for <b>HCV (Anti-HCV / PCR)</b>! Treat with <mark class=\"hl rx\"><b>High-Potency Topical Corticosteroids</b></mark> (or intralesional Triamcinolone, oral Prednisone if widespread/erosive oral).</li>\n</ul><h3><b>B. Pityriasis Rosea (Self-Limited Viral-Linked Rash!)</b></h3><ul>\n<li class=\"l1\"><b>Classic Course (Young Adults 10–35 Yrs):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\">Begins with a single <b>2–10 cm oval erythematous plaque with central clearing and fine \"collarette\" of scale</b> (<b>\"Herald Patch\"</b>) on trunk!</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\">Followed 1–2 weeks later by a widespread eruption of smaller oval salmon-colored plaques aligned along skin cleavage lines on the back in a <b>\"Christmas Tree\" Pattern</b> (<b>classically SPARES palms &amp; soles!</b>).</span></p>\n<ul>\n<li class=\"l1\"><b>CRITICAL RULE:</b> <b>MUST RULE OUT SECONDARY SYPHILIS (Do RPR/VDRL)</b> if atypical or if <b>palms/soles are involved</b>!</li>\n<li class=\"l1\"><b>Treatment:</b> <b>Reassurance ONLY</b> (resolves spontaneously in <b>6–8 weeks</b>!); topical steroids / oral antihistamines if itchy.</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u266\">← Case 4</button><button class=\"nv\" data-u=\"u268\">Case 6 →</button></nav></article><article class=\"view unit\" id=\"u268\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 6</span><h1>Urticaria (HIVES) &amp; Angioedema</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Urticaria+%28HIVES%29+%26+Angioedema\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><ul>\n<li class=\"l1\"><b>Urticaria:</b> Transient, intensely pruritic, raised erythematous edematous plaques (<b>wheals</b>) with central pallor caused by mast cell <b>histamine</b> release in the <b>superficial dermis</b>. <b>Key Rule: Individual wheals last &lt; 24 hours and fade without bruising or scarring!</b> <i>(If a lesion lasts &gt; 24 hrs or leaves bruising -&gt; suspect </i><i><b>Urticarial Vasculitis</b></i><i> and biopsy!)</i></li>\n<li class=\"l1\"><b>Angioedema:</b> Deeper subcutaneous/submucosal swelling (lips, eyelids, tongue, larynx, bowel).</li>\n</ul><h3><b>2. Etiology (Separated — Acute [&lt; 6 Weeks] vs. Chronic [≥ 6 Weeks])</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Acute Urticaria (&lt; 6 Weeks):</b> Viral infections (#1 overall in kids!), Foods (nuts, shellfish, eggs), Drugs (<mark class=\"hl rx\"><b> Penicillins, NSAIDs, Aspirin, Opiates, Radiocontrast</b></mark> ), Insect stings.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Chronic Spontaneous Urticaria (≥ 6 Weeks — ~80% Idiopathic/Autoimmune):</b> Autoantibodies against IgE/FcεRI receptor, Thyroid autoimmunity, <i>H. pylori</i>; <b>Physical/Inducible Urticarias</b> (Dermatographism, Cold, Cholinergic [sweat/exercise], Solar, Pressure).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Isolated Angioedema WITHOUT Urticaria (CRITICAL DIFFERENTIATION!):</b></span></p>\n<ul>\n<li class=\"l2\"><b>ACE-Inhibitor Induced Angioedema</b> (bradykinin-mediated — can occur even <b>years</b> after starting Ramipril/Enalapril!).</li>\n<li class=\"l2\"><b>Hereditary Angioedema (HAE):</b> Autosomal dominant <b>C1-Esterase Inhibitor Deficiency</b> (<b>Low C4</b>!) -&gt; recurrent laryngeal/abdominal edema; <mark class=\"hl rx\"><b>DOES NOT respond to Epinephrine, Antihistamines, or Steroids</b></mark> -&gt; give <b>C1-Inhibitor Concentrate</b> or <b>Icatibant</b> (or FFP if unavailable)!</li>\n</ul><h3><b>3. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Always Check Airway First:</b> If stridor, tongue swelling, wheezing, or hypotension -&gt; <mark class=\"hl rx\"><b>Anaphylaxis -&gt; IM Epinephrine 0.3–0.5 mg IMMEDIATELY!</b></mark></li>\n<li class=\"l1\"><b>Uncomplicated Acute/Chronic Urticaria:</b></li>\n<li class=\"l2\"><b>First-Line:</b> <b>2nd-Generation Non-Sedating H1 Antihistamine</b> (<b>Cetirizine, Loratadine, Fexofenadine, Desloratadine</b>) daily -&gt; if uncontrolled in Chronic Urticaria, <b>uptitrate up to 4× standard daily dose</b>!</li>\n<li class=\"l2\"><i>Add-on:</i> Short <mark class=\"hl rx\"><b>3–5 day oral Prednisone</b></mark> burst if severe refractory acute flare; <b>Omalizumab</b> (Anti-IgE) for refractory Chronic Spontaneous Urticaria!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u267\">← Case 5</button><button class=\"nv\" data-u=\"u269\">Case 7 →</button></nav></article><article class=\"view unit\" id=\"u269\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 7</span><h1>Impetigo, Ecthyma &amp; Folliculitis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Impetigo%2C+Ecthyma+%26+Folliculitis\">🔍 Search on Google</a></header><h3><b>1. Impetigo (#1 Pediatric Bacterial Skin Infection!)</b></h3><ul>\n<li class=\"l1\"><b>Etiology:</b> <i><b>Staphylococcus aureus</b></i> (#1 overall — also causes <b>Bullous Impetigo</b> via exfoliative toxins) and <i><b>Streptococcus pyogenes</b></i><b> (GAS)</b>.</li>\n<li class=\"l1\"><b>Clinical Picture:</b> Superficial epidermal infection around <b>nose and mouth</b> (or limbs) forming fragile vesicles/pustules that rupture into classic <b>\"Honey-Colored\" (golden-yellow) Crusts</b>!</li>\n<li class=\"l1\"><i>(Note: </i><i><b>Ecthyma</b></i><i> = deeper \"punched-out\" ulcerative form extending into dermis, healing with scars; </i><mark class=\"hl lab\"><i><b>PSGN</b></i></mark><i> [Post-Streptococcal Glomerulonephritis] can follow GAS impetigo in 3–6 weeks!)</i></li>\n<li class=\"l1\"><b>Treatment:</b></li>\n<li class=\"l2\"><i>Localized (Few lesions):</i> <b>Topical Mupirocin 2%</b> (or Fusidic Acid / Retapamulin) TID × 5–7 days + gentle crust washing!</li>\n<li class=\"l2\"><i>Extensive / Bullous / Outbreak / Ecthyma:</i> <b>Oral Cephalexin</b> or <b>Dicloxacillin</b> or <mark class=\"hl rx\"><b>Amoxicillin-Clavulanate</b></mark> (or <mark class=\"hl rx\"><b>TMP-SMX / Clindamycin / Doxycycline</b></mark> if <b>CA-MRSA </b>suspected) × 7 days!</li>\n</ul><h3><b>2. Folliculitis</b></h3><ul>\n<li class=\"l1\">Superficial inflammation of hair follicles (pustules pierced by a hair shaft):</li>\n<li class=\"l2\"><i>S. aureus:</i> Most common (beards, thighs, buttocks).</li>\n<li class=\"l2\"><i>\"Hot-Tub Folliculitis\":</i> <i><b>Pseudomonas aeruginosa</b></i> (truncal/swimsuit distribution after contaminated hot tub/pool — self-limited!).</li>\n<li class=\"l2\"><i>Pseudofolliculitis Barbae (\"Razor Bumps\"):</i> Mechanical ingrown beard hairs (NOT bacterial! Treat by growing beard/electric clippers + topical retinoid/glycolic acid!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u268\">← Case 6</button><button class=\"nv\" data-u=\"u270\">Case 8 →</button></nav></article><article class=\"view unit\" id=\"u270\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 8</span><h1>Herpes Simplex Virus (HSV-1 &amp; HSV-2) &amp; Eczema Herpeticum</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Herpes+Simplex+Virus+%28HSV-1+%26+HSV-2%29+%26+Eczema+Herpeticum\">🔍 Search on Google</a></header><h3><b>1. Etiology &amp; Latency</b></h3><ul>\n<li class=\"l1\"><b>HSV-1:</b> Primarily orolabial (<b>Cold Sores / Herpes Labialis</b>; rising cause of genital herpes). Remains latent in <b>Trigeminal Ganglion</b>.</li>\n<li class=\"l1\"><b>HSV-2:</b> Primarily genital herpes. Remains latent in <b>Sacral Dorsal Root Ganglia</b>.</li>\n</ul><h3><b>2. Clinical Picture &amp; Diagnosis</b></h3><ul>\n<li class=\"l1\">Prodrome of tingling/burning -&gt; <b>Grouped (\"clustered\") painful vesicles on an erythematous base (\"Dewdrops on an Erythematous Base\")</b> -&gt; rapidly unroof into shallow punched-out ulcers -&gt; crust over 7–14 days!</li>\n<li class=\"l1\"><i>Diagnostic Tests:</i> Clinical; <b>PCR</b> (Gold Standard!) or <b>Tzanck Smear</b> (shows <b>Multinucleated Giant Cells</b> — cannot distinguish HSV from VZV!).</li>\n</ul><h3><b>3. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Oral Nucleoside Analogues (Most effective if started within &lt; 48–72 hrs!):</b></li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>Acyclovir</b></mark> , <mark class=\"hl rx\"><b>Valacyclovir</b></mark> (better bioavailability, BID dosing!), or <b>Famciclovir</b>.</li>\n<li class=\"l2\"><i>Recurrent Genital HSV (≥ 6 episodes/year):</i> Daily <mark class=\"hl rx\"><b>Suppressive Valacyclovir</b></mark> (reduces recurrences &amp; partner transmission!).</li>\n<li class=\"l2\"><i>Pregnancy Near Term With Active Genital Lesions/Prodrome:</i> <mark class=\"hl rx\"><b>Suppressive Acyclovir from 36 weeks</b></mark> ; <b>Cesarean Section MANDATORY</b> if active lesions at labor!</li>\n<li class=\"l2\"><i>Eczema Herpeticum / HSV Encephalitis / Neonatal HSV:</i> <mark class=\"hl rx\"><b>Immediate IV Acyclovir</b></mark> !</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u269\">← Case 7</button><button class=\"nv\" data-u=\"u271\">Case 9 →</button></nav></article><article class=\"view unit\" id=\"u271\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 9</span><h1>Herpes Zoster (SHINGLES) &amp; Postherpetic Neuralgia (PHN)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Herpes+Zoster+%28SHINGLES%29+%26+Postherpetic+Neuralgia+%28PHN%29\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Pathophysiology</b></h3><p>Reactivation of latent <b>VZV</b> (Varicella-Zoster Virus — Chickenpox) within a sensory dorsal root ganglion due to age-related decline in cell-mediated immunity (<b>&gt; 50–60 years</b> or immunocompromised!).</p><h3><b>2. Clinical Picture (DOES NOT CROSS THE MIDLINE!)</b></h3><ul>\n<li class=\"l1\"><b>Prodrome (2–4 Days):</b> Unilateral <b>burning, tingling, or hyperesthetic pain</b> along a single <b>dermatome</b> (thoracic/lumbar #1 — often misdiagnosed as MI, renal colic, or cholecystitis before rash appears!).</li>\n<li class=\"l1\"><b>Rash:</b> <b>Grouped vesicles on an erythematous base strictly restricted to ONE unilateral dermatome</b> (never crosses midline!).</li>\n<li class=\"l1\"><b>CRITICAL SPECIAL SITES:</b></li>\n<li class=\"l2\"><mark class=\"hl lab\"><b>Herpes Zoster Ophthalmicus (CN V1):</b></mark> Tip-of-nose vesicles (<b>Hutchinson’s Sign</b>) strongly predict <b>ocular/corneal involvement</b> -&gt; <b>URGENT Ophthalmology Consult + Systemic Antivirals!</b></li>\n<li class=\"l2\"><b>Ramsay Hunt Syndrome (Geniculate Ganglion — CN VII/VIII):</b> Ipsilateral <b>LMN Facial Palsy</b> + ear canal vesicles + vertigo/hearing loss!</li>\n</ul><h3><b>3. Treatment (Start Within 72 Hours of Rash Onset!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Oral Antivirals × 7 Days:</b> <mark class=\"hl rx\"><b>Valacyclovir 1,000 mg TID</b></mark> (preferred) OR <b>Famciclovir 500 mg TID</b> OR <mark class=\"hl rx\"><b>Acyclovir 800 mg 5×/day</b></mark> <i>(Use </i><mark class=\"hl rx\"><i><b>IV Acyclovir</b></i></mark><i> if immunocompromised, disseminated &gt; 2 dermatomes, or CNS involvement!)</i>.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Pain &amp; PHN Prevention:</b> Acetaminophen/NSAIDs; for <b>Postherpetic Neuralgia (pain &gt; 3 months)</b> -&gt; <mark class=\"hl rx\"><b>Gabapentin, Pregabalin, Amitriptyline, or Topical Lidocaine/Capsaicin</b></mark> !</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Prevention:</b> <b>Recombinant Zoster Vaccine (Shingrix)</b> for ALL adults <b>≥ 50 years</b>! <i>(Patients with active shingles are infectious via direct contact to non-immune pregnant women/infants until lesions crust -&gt; causes chickenpox!)</i></span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u270\">← Case 8</button><button class=\"nv\" data-u=\"u272\">Case 10 →</button></nav></article><article class=\"view unit\" id=\"u272\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 10</span><h1>Viral Warts (VERRUCAE) &amp; Molluscum Contagiosum</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Viral+Warts+%28VERRUCAE%29+%26+Molluscum+Contagiosum\">🔍 Search on Google</a></header><h3><b>A. Viral Warts (</b><b>Verrucae</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Etiology:</b> <b>HPV</b> (Human Papillomavirus — benign skin types e.g., <b>HPV 1, 2, 4</b>; anogenital condylomata acuminata = <b>HPV 6 &amp; 11</b>!).</li>\n<li class=\"l1\"><b>Clinical Clues:</b> Hyperkeratotic verrucous papules with <b>loss of skin lines</b> and <b>black pinpoint dots (thrombosed capillaries)</b> when pared! (<i>Plantar warts</i> on soles are painful when squeezed side-to-side, unlike calluses which hurt on direct pressure!).</li>\n<li class=\"l1\"><b>Treatment:</b> Many regress spontaneously in kids; <b>Salicylic Acid 17–40% daily</b> (first-line home therapy) or <b>Liquid Nitrogen Cryotherapy</b> (q2–3 wks); <b>Imiquimod / Podophyllotoxin / Cryotherapy</b> for genital warts.</li>\n</ul><h3><b>B. Molluscum Contagiosum</b></h3><ul>\n<li class=\"l1\"><b>Etiology:</b> <b>Poxvirus</b> (<b>Molluscum Contagiosum Virus</b>) — spread by direct skin-to-skin contact (children/swimming pools, or sexually in adults!).</li>\n<li class=\"l1\"><b>Clinical Picture:</b> Discrete, smooth, <b>pearly/flesh-colored dome-shaped papules with CLASSIC CENTRAL UMBILICATION</b>!</li>\n<li class=\"l1\"><b>Treatment:</b> <b>Benign &amp; self-limited</b> (resolves within 6–18 months in healthy kids — reassurance is often best!); if bothersome/genital -&gt; <b>Curettage, Cryotherapy, or Cantharidin</b>! <i>(Extensive giant facial molluscum in an adult -&gt; </i><i><b>Test for HIV</b></i><i>!)</i></li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u271\">← Case 9</button><button class=\"nv\" data-u=\"u273\">Case 11 →</button></nav></article><article class=\"view unit\" id=\"u273\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 11</span><h1>Dermatophytosis (SUPERFICIAL FUNGAL &quot;TINEA&quot; INFECTIONS)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Dermatophytosis+%28SUPERFICIAL+FUNGAL+%22TINEA%22+INFECTIONS%29\">🔍 Search on Google</a></header><h3><b>1. Etiology (Dermatophytes — Invade Keratin Only: Skin, Hair, Nails!)</b></h3><p><i><b>Trichophyton</b></i> (most common: <i>T. rubrum</i>, <i>T. tonsurans</i>), <i><b>Microsporum</b></i> (<i>M. canis</i> from cats/dogs!), and <i><b>Epidermophyton</b></i>.</p><h3><b>2. Clinical Subtypes &amp; Specific Treatments (CRITICAL: Distinguish Scalp/Nail vs. Skin!)</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>Subtype</b></p></th><th><p><b>Classic Presentation</b></p></th><th><p><b>Key Pearl</b></p></th><th><p><b>Treatment</b></p></th></tr><tr><td><p><b>Tinea Corporis</b> <i>(Ringworm)</i></p></td><td><p><b>Annular erythematous plaques with an active scaly raised border &amp; central clearing</b></p></td><td><p><b>NEVER apply Topical Steroids alone</b> -&gt; masks inflammation &amp; worsens fungus (<b>\"Tinea Incognito\"</b>)!</p></td><td><p><b>Topical Azoles</b> (Clotrimazole/Miconazole/Ketoconazole) or <b>Topical Terbinafine</b> BID × 2–4 wks!</p></td></tr><tr><td><p><b>Tinea Cruris</b> <i>(\"Jock Itch\")</i></p></td><td><p>Pruritic erythematous scaly plaques with raised border in <b>inguinal folds (SPARES SCROTUM!)</b></p></td><td><p>Unlike Candida, Tinea <b>spares the scrotum</b>!</p></td><td><p>Keep groin dry + <b>Topical Terbinafine or Azole</b> × 2–4 wks!</p></td></tr><tr><td><p><b>Tinea Pedis</b> <i>(\"Athlete’s Foot\")</i></p></td><td><p>Macerated fissured scaling between <b>4th &amp; 5th toes </b>(interdigital) or \"moccasin\" dry sole scaling</p></td><td><p>Portal of entry for lower-leg <mark class=\"hl lab\"><b>Cellulitis</b></mark> !</p></td><td><p><b>Topical Terbinafine / Azole</b> × 4 wks + dry between toes!</p></td></tr><tr><td><p><b>Tinea Capitis</b> <i>(Scalp — </i><i><b>Children!</b></i><i>)</i></p></td><td><p>Scaly patches of <b>alopecia with \"black dots\"</b> (broken hair shafts), <b>Kerion</b> (boggy pus-oozing inflammatory plaque + cervical nodes — often misdiagnosed as bacterial abscess!)</p></td><td><p><mark class=\"hl lab\"><b>TOPICAL CREAMS DO NOT PENETRATE HAIR FOLLICLES — SYSTEMIC ORAL THERAPY IS MANDATORY!</b></mark></p></td><td><p><b>Oral Griseofulvin</b> (6–8 wks — best for <i>Microsporum</i>) OR <b>Oral Terbinafine</b> (4–6 wks — best for <i>Trichophyton</i>) + <b>Ketoconazole/Selenium Sulfide shampoo</b>!</p></td></tr><tr><td><p><b>Onychomycosis</b> <i>(Tinea Unguium)</i></p></td><td><p>Thickened, yellow/brittle nails with subungual debris &amp; onycholysis</p></td><td><p>Confirm with <b>KOH prep / PAS nail clipping</b> before months of oral pills!</p></td><td><p><b>Oral Terbinafine</b> (<b>6 wks fingernails / 12 wks toenails</b> — check baseline LFTs!) or Itraconazole pulse!</p></td></tr></table><ul>\n<li class=\"l1\"><b>Bedside Diagnostic Confirmation:</b> <b>KOH (10–20% Potassium Hydroxide) Prep</b> of skin/nail scrapings -&gt; shows <b>Septate Branching Hyphae</b>!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u272\">← Case 10</button><button class=\"nv\" data-u=\"u274\">Case 12 →</button></nav></article><article class=\"view unit\" id=\"u274\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 12</span><h1>Tinea Versicolor &amp; Cutaneous Candidiasis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Tinea+Versicolor+%26+Cutaneous+Candidiasis\">🔍 Search on Google</a></header><h3><b>A. Tinea (Pityriasis) Versicolor (</b><b>Extremely Common in Egyptian Summers!</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Etiology:</b> Overgrowth of normal skin yeast <i><b>Malassezia furfur</b></i> (lipophilic — triggered by heat, humidity, sweating, oily skin, steroids!).</li>\n<li class=\"l1\"><b>Clinical Picture:</b> Multiple well-demarcated <b>hypopigmented, hyperpigmented, or salmon-colored macules with fine powdery scale</b> over <b>upper chest, back, neck, and upper arms</b>.</li>\n<li class=\"l1\"><b>Diagnosis:</b> <b>KOH Prep</b> shows classic <b>\"Spaghetti and Meatballs\"</b> (short curved hyphae + yeast clusters); Wood’s lamp shows yellow-green fluorescence.</li>\n<li class=\"l1\"><b>Treatment:</b> <b>Topical Selenium Sulfide 2.5% lotion/shampoo</b> or <b>Ketoconazole 2% shampoo</b> applied as body wash (10 min daily × 1–2 wks) or <mark class=\"hl rx\"><b>Oral Fluconazole</b></mark> (if extensive — <i>NOT Terbinafine, which fails in Malassezia!</i>). <i>Warn patient: skin color takes </i><i><b>months</b></i><i> to re-pigment even after fungus is dead!</i></li>\n</ul><h3><b>B. Cutaneous &amp; Mucocutaneous Candidiasis (</b><b>Candida albicans</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Intertrigo (Skin Folds / Axillae / Inframammary / Diaper Area):</b> Beefy-red, moist macerated plaques with characteristic <b>\"Satellite\" Papules and Pustules</b> beyond the border (<b>INVOLVES skin creases &amp; scrotum</b>, unlike Tinea cruris!).</li>\n<li class=\"l1\"><b>Oral Thrush (Pseudomembranous Candidiasis):</b> Creamy white plaques on tongue/buccal mucosa that <b>scrape off leaving a bleeding erythematous base</b>! <i>(Screen for HIV/DM/inhaled steroid misuse!).</i></li>\n<li class=\"l1\"><b>Treatment:</b> Keep dry + <b>Topical Nystatin, Clotrimazole, or Miconazole</b> (add mild hydrocortisone briefly if severe diaper inflammation); <mark class=\"hl rx\"><b>Oral Fluconazole</b></mark> or Nystatin swish-and-swallow for thrush!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u273\">← Case 11</button><button class=\"nv\" data-u=\"u275\">Case 13 →</button></nav></article><article class=\"view unit\" id=\"u275\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 13</span><h1>Scabies (SARCOPTES SCABIEI)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Scabies+%28SARCOPTES+SCABIEI%29\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Transmission</b></h3><p>Intensely pruritic skin infestation caused by the human itch mite <i><b>Sarcoptes scabiei</b></i><b> var. </b><i><b>hominis</b></i>, transmitted via <b>prolonged direct skin-to-skin contact</b> (household crowding, schools, nursing homes) or shared bedding/clothes.</p><h3><b>2. Clinical Picture (PATHOGNOMONIC CLUE: INTENSE ITCHING WORSE AT NIGHT + AFFECTED FAMILY MEMBERS!)</b></h3><ul>\n<li class=\"l1\"><b>Classic Distribution:</b> <b>Interdigital finger webspaces</b>, <b>flexor wrists</b>, <b>axillary folds</b>, <b>periumbilical skin</b>, <b>male genitalia (scrotum/penis — pathognomonic pruritic nodules!)</b>, female areolae, and buttocks — <mark class=\"hl mech\"><b>CLASSICAL SCABIES SPARES FACE/SCALP IN ADULTS</b></mark> <i>(except infants/elderly/Crusted Scabies, where palms, soles, face &amp; scalp ARE involved!)</i>.</li>\n<li class=\"l1\"><b>Lesions:</b> <b>Linear Burrows</b> (2–10 mm wavy gray lines), excoriated papules, secondary impetigo.</li>\n<li class=\"l1\"><b>Crusted (\"Norwegian\") Scabies:</b> Hyperkeratotic thick scaly plaques teeming with millions of mites in <b>immunocompromised / elderly / neurological patients</b> -&gt; hyper-contagious!</li>\n</ul><h3><b>3. Diagnosis &amp; Treatment (CRITICAL HOUSEHOLD RULES!)</b></h3><ul>\n<li class=\"l1\"><b>Diagnosis:</b> Clinical (or skin scraping of burrow under mineral oil showing <b>mites, eggs, or scybala [fecal pellets]</b>).</li>\n<li class=\"l1\"><b>Treatment:</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>First-Line:</b> <b>Permethrin 5% Cream</b> applied <b>from neck down to toes</b> (include head/scalp in infants/elderly!) before bedtime, left on <b>8–14 hours</b>, then washed off -&gt; <b>REPEAT IN 7 DAYS</b> (kills newly hatched nymphs!). <i>(Alternative/Oral: </i><i><b>Oral Ivermectin 200 mcg/kg</b></i><i> Day 1 &amp; Day 8–14 — first-line alongside Permethrin for Crusted Scabies! Safe in pregnancy/infants: Permethrin 5% or Sulfur ointment).</i></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>MANDATORY:</b> <mark class=\"hl lab\"><b>Treat ALL close household/sexual contacts SIMULTANEOUSLY</b></mark> (even if asymptomatic!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Decontamination:</b> Wash bedding/clothes used in past 3 days in <b>hot water &amp; hot dryer</b> (or seal in plastic bag for ≥ 72 hrs — mites die off human host in 2–3 days!).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Warn Patient:</b> <b>Post-scabetic itching can persist for 2–4 weeks</b> after mites are dead (hypersensitivity reaction — treat with antihistamines &amp; topical steroids, do NOT keep repeating Permethrin unnecessarily!).</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u274\">← Case 12</button><button class=\"nv\" data-u=\"u276\">Case 14 →</button></nav></article><article class=\"view unit\" id=\"u276\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 14</span><h1>Pediculosis (LICE) &amp; Cutaneous Leishmaniasis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pediculosis+%28LICE%29+%26+Cutaneous+Leishmaniasis\">🔍 Search on Google</a></header><h3><b>A. Pediculosis (Lice — Head, Body, Pubic)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Pediculosis Capitis (Head Lice — </b><i><b>Pediculus humanus capitis</b></i><b>, Very Common in Schoolchildren!):</b></span></p>\n<ul>\n<li class=\"l2\">Intense scalp pruritus (occiput/retroauricular); <b>Nits (tiny oval white eggs firmly cemented to hair shafts within &lt; 6 mm of scalp — do NOT flake off like dandruff!)</b>.</li>\n<li class=\"l2\"><i>Treatment:</i> <b>Permethrin 1% lotion</b> (or Dimethicone / Malathion / Ivermectin lotion) applied to hair × 10 min + <b>fine-tooth wet combing</b> -&gt; <b>repeat in 7–10 days</b>!</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Pediculosis Corporis (Body Lice):</b> Mites live in <b>clothing SEAMS</b> (homeless/crowded camps — transmits <i>Typhus/Trench fever</i>!) -&gt; <b>Wash/boil/discard clothes</b>!</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Pediculosis Pubis (\"Crabs\"):</b> STI -&gt; check for other STIs; treat with Permethrin 1% + treat partner!</span></p><h3><b>B. Cutaneous Leishmaniasis (</b><b>Middle East / Sinai / Rural Egypt Relevance!</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Etiology:</b> Protozoan <i><b>Leishmania major / tropica</b></i> transmitted by bite of female <b>Sandfly (</b><i><b>Phlebotomus</b></i><b>)</b>.</li>\n<li class=\"l1\"><b>Clinical Picture:</b> Chronic, painless, slowly enlarging papule/nodule on <b>exposed skin (face, hands, forearms)</b> that ulcerates into a classic <b>\"Volcano-Like\" Ulcer with raised indurated borders</b> lasting months (\"1-year sore\")!</li>\n<li class=\"l1\"><b>Diagnosis &amp; Treatment:</b> Skin scraping/biopsy showing <b>intracellular Amastigotes (Leishman-Donovan bodies)</b> inside macrophages! Small self-healing lesions: observe or <b>Intralesional Sodium Stibogluconate / Meglumine Antimoniate</b> or Cryotherapy; large/facial/disfiguring: <mark class=\"hl rx\"><b>Systemic Antimonials, Liposomal Amphotericin B, or Oral Miltefosine</b></mark> .</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u275\">← Case 13</button><button class=\"nv\" data-u=\"u277\">Case 15 →</button></nav></article><article class=\"view unit\" id=\"u277\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 15</span><h1>Erythema Multiforme (EM) vs. SJS / TEN (DERMATOLOGIC EMERGENCY!)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Erythema+Multiforme+%28EM%29+vs.+SJS+%2F+TEN+%28DERMATOLOGIC+EMERGENCY%21%29\">🔍 Search on Google</a></header><h3><b>1. Crucial Spectrum Comparison (SJS / TEN Are True Burn-Unit Emergencies!)</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>Feature</b></p></th><th><p><b>Erythema Multiforme (EM)</b></p></th><th><p><mark class=\"hl lab\"><b>Stevens-Johnson Syndrome (SJS) &amp; TEN</b></mark></p></th></tr><tr><td><p><b>#1 Etiology (Separated!)</b></p></td><td><p><b>INFECTIONS (&gt; 90%):</b> <i><b>Herpes Simplex Virus (HSV)</b></i> (#1</p>\n<p>overall!) and <i><b>Mycoplasma pneumoniae</b></i>!</p></td><td><p><b>DRUGS (&gt; 80–90%):</b> <mark class=\"hl rx\"><b>Allopurinol</b></mark> , <b>Sulfonamides (TMP-SMX)</b>,</p>\n<p><b>Anticonvulsants (Lamotrigine, Carbamazepine, Phenytoin, Phenobarbital)</b>, <mark class=\"hl rx\"><b>NSAIDs (Oxicams)</b></mark> , Nevirapine! <i>(Mycoplasma rarely)</i></p></td></tr><tr><td><p><b>Classic Lesion</b></p></td><td><p><b>Symmetric \"Target / Iris\" Lesions</b> (3 concentric zones:</p></td><td><p><b>Flat atypical dusky macules/purpura -&gt; Painful Blisters &amp; FULL-</b></p></td></tr><tr><td><p><b>Classic Lesion</b></p></td><td><p><b>Symmetric Target / Iris Lesions</b> (3 concentric zones: central dusk/vesicle + pale ring + red outer ring) on <b>Palms, Soles, Extensors</b>!</p></td><td><p><b>Flat atypical dusky macules/purpura -&gt; Painful Blisters &amp; FULL-THICKNESS EPIDERMAL SLOUGHING!</b></p></td></tr><tr><td><p><b>Nikolsky Sign</b></p></td><td><p><b>Negative</b></p></td><td><p><b>POSITIVE</b> (gentle lateral pressure shears epidermis off!)</p></td></tr><tr><td><p><b>Mucosal Involvement</b></p></td><td><p>Absent (EM minor) or Mild 1 site (EM major)</p></td><td><p><b>SEVERE ≥ 2 Mucosal Surfaces (&gt; 90%):</b> Hemorrhagic crusted <b>lips/mouth</b>, severe <b>conjunctivitis</b> (risk of blindness!), genital/urethral erosions!</p></td></tr><tr><td><p><b>% BSA Detachment</b></p></td><td><p>&lt; 10% (no true sheets of sloughing)</p></td><td><p><mark class=\"hl lab\"><b>SJS:</b></mark> <b>&lt; 10% BSA</b> | <mark class=\"hl lab\"><b>SJS/TEN Overlap:</b></mark> <b>10–30% BSA</b> | <mark class=\"hl lab\"><b>TEN:</b></mark> <b>&gt; 30% BSA</b>!</p></td></tr><tr><td><p><b>Treatment</b></p></td><td><p>Treat underlying HSV (Acyclovir) or <i>Mycoplasma</i> + symptomatic topical steroids/antihistamines</p></td><td><p><b>IMMEDIATE STOP OF CULPRIT DRUG</b> + <b>Admit to Burn Unit / ICU </b>(fluid/electrolyte resuscitation, sterile non-adherent wound care, <b>early Ophthalmology consult</b>, nutrition, infection surveillance)! <i>(Avoid empirical prophylactic antibiotics unless sepsis!)</i></p></td></tr></table><p class=\"muted\"><i>End of Part 11A — Dermatology (Cases 1–15 Complete!).</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u276\">← Case 14</button><button class=\"nv\" data-u=\"u278\">Case 16 →</button></nav></article><article class=\"view unit\" id=\"u278\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 16</span><h1>Pemphigus Vulgaris vs. Bullous Pemphigoid</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pemphigus+Vulgaris+vs.+Bullous+Pemphigoid\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Chronic autoimmune blistering diseases driven by <b>IgG</b> (Immunoglobulin G) autoantibodies targeting epidermal or dermo-epidermal adhesion molecules.</p><h3><b>2. Crucial Clinical &amp; Pathologic Comparison</b></h3><table class=\"t \"><tr><td><p><b>Feature</b></p></td><td><p><b>Pemphigus Vulgaris (PV) </b><i><b>(More Severe!)</b></i></p></td><td><p><b>Bullous Pemphigoid (BP) </b><i><b>(#1 Autoimmune Blistering Disease Overall!)</b></i></p></td></tr><tr><td><p><b>Target Antigen</b></p></td><td><p><b>Desmoglein 3 (and 1)</b> — <b>Desmosomes</b> between keratinocytes (<i>Intraepidermal</i> split!)</p></td><td><p><b>BP180 &amp; BP230</b> — <b>Hemidesmosomes</b> at dermo-epidermal junction (<i>Subepidermal</i> split!)</p></td></tr><tr><td><p><b>Typical Age</b></p></td><td><p>Middle-aged adults (<b>40–60 years</b>)</p></td><td><p><b>Elderly (&gt; 65–70 years)</b></p></td></tr><tr><td><p><b>Blister Morphology</b></p></td><td><p><b>FLACCID, fragile blisters</b> that rupture easily leaving <b>painful raw weeping erosions</b>!</p></td><td><p><mark class=\"hl lab\"><b>TENSE, firm, dome-shaped blisters</b></mark> on erythematous/urticarial skin (<b>do NOT rupture easily!</b>), intensely <b>pruritic</b>!</p></td></tr><tr><td><p><b>Mucosal Involvement</b></p></td><td><p><b>ALMOST ALWAYS (&gt; 80–90%)</b> — painful <b>oral erosions</b> often appear MONTHS before skin!</p></td><td><p><b>RARE / ABSENT (~10–20%)</b></p></td></tr><tr><td><p><b>Nikolsky Sign</b></p></td><td><p><b>POSITIVE</b> (skin shears off on lateral pressure)</p></td><td><p><b>NEGATIVE</b></p></td></tr><tr><td><p><b>Histopathology &amp; DIF</b> <i>(Direct Immunofluorescence)</i></p></td><td><p>Suprabasal acantholysis (<b>\"Row of Tombstones\"</b>); <b>DIF:</b> <b>\"Fish-net / Chicken-wire\"</b> intercellular IgG!</p></td><td><p>Subepidermal blister with <b>eosinophils</b>; <b>DIF:</b> <b>Linear IgG &amp; C3 </b>band along basement membrane!</p></td></tr><tr><td><p><b>Treatment</b></p></td><td><p><mark class=\"hl rx\"><b>High-Dose Systemic Corticosteroids</b></mark></p>\n<p>(<mark class=\"hl rx\"><b> Prednisone 1 mg/kg/day</b></mark> ) + <mark class=\"hl rx\"><b>Rituximab</b></mark> (First-Line steroid-sparing!) or Azathioprine / <b>MMF </b>(Mycophenolate Mofetil)</p></td><td><p><b>Superpotent Topical Clobetasol</b> (often enough for mild/localized!) OR moderate-dose <mark class=\"hl rx\"><b>Oral Prednisone</b></mark> + <mark class=\"hl rx\"><b>Doxycycline + Nicotinamide</b></mark> / Methotrexate / MMF</p></td></tr></table><nav class=\"un\"><button class=\"nv\" data-u=\"u277\">← Case 15</button><button class=\"nv\" data-u=\"u279\">Case 17 →</button></nav></article><article class=\"view unit\" id=\"u279\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 17</span><h1>Vitiligo &amp; Melasma</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Vitiligo+%26+Melasma\">🔍 Search on Google</a></header><h3><b>A. Vitiligo</b></h3><ul>\n<li class=\"l1\"><b>Definition:</b> Acquired autoimmune destruction of epidermal <b>melanocytes</b> causing well-demarcated <b>chalk-white (depigmented)</b> macules and patches.</li>\n<li class=\"l1\"><b>Key Associations (SCREEN FOR AUTOIMMUNE OVERLAP!):</b> <b>Autoimmune Thyroiditis (Hashimoto’s / Graves’ — #1!)</b>, Type 1 <b>DM</b> (Diabetes Mellitus), Pernicious Anemia, Addison’s Disease, Alopecia Areata!</li>\n<li class=\"l1\"><b>Clinical Picture:</b> Symmetrical depigmented patches (face/periorificial, dorsal hands, elbows, knees, genitalia) + <b>Koebner phenomenon</b> + <b>Leukotrichia</b> (white hairs inside patch = harder to repigment!). <b>Wood’s Lamp</b> shows <b>bright chalk-white accentuation</b> (distinguishes from hypopigmented <i>Pityriasis alba</i> or <i>Tinea versicolor</i>!).</li>\n<li class=\"l1\"><b>Treatment:</b></li>\n<li class=\"l2\"><i>Localized:</i> <mark class=\"hl rx\"><b>Potent Topical Corticosteroids</b></mark> (body) or <mark class=\"hl rx\"><b>Topical Calcineurin Inhibitors (Tacrolimus)</b></mark> (face/eyelids!) + <b>Topical Ruxolitinib (JAK inhibitor)</b> cream!</li>\n<li class=\"l2\"><i>Widespread (&gt; 10% BSA [Body Surface Area]):</i> <b>NB-UVB</b> (Narrowband Ultraviolet B) Phototherapy × 6–12 months + short oral steroid mini-pulses if rapidly spreading!</li>\n</ul><h3><b>B. Melasma (</b><b>Extremely Common in Egyptian Women!</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Etiology (Separated):</b> <b>(1) UV (Ultraviolet) &amp; Visible Light Exposure</b>, <b>(2) Hormonal Triggers</b> (<b>Pregnancy [\"Chloasma / Mask of Pregnancy\"]</b>, <b>COCs</b> [Combined Oral Contraceptives]), <b>(3) Genetic Predisposition</b> (darker Fitzpatrick skin types III–V!).</li>\n<li class=\"l1\"><b>Clinical Picture:</b> Symmetric, blotchy <b>brown-gray hyperpigmented patches</b> over <b>cheeks (malar), forehead, upper lip, and chin</b>.</li>\n<li class=\"l1\"><b>Treatment:</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Strict Daily Broad-Spectrum Sunscreen (SPF ≥ 50 WITH Iron Oxide to block Visible Light!) + Sun Avoidance</b> (WITHOUT this, ALL creams fail!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Topical Triple Combination Cream (Kligman Formula):</b> <b>Hydroquinone 4% + Tretinoin 0.05% + Fluocinolone (mild steroid)</b> nightly for 8–12 weeks (or Azelaic acid / Vitamin C / Kojic acid / Tranexamic acid)! <i>(Caution: Prolonged unsupervised Hydroquinone can cause paradoxical </i><i><b>Exogenous Ochronosis</b></i><i>!).</i></span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u278\">← Case 16</button><button class=\"nv\" data-u=\"u280\">Case 18 →</button></nav></article><article class=\"view unit\" id=\"u280\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 18</span><h1>Alopecia Areata, Androgenetic Alopecia &amp; Telogen Effluvium</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Alopecia+Areata%2C+Androgenetic+Alopecia+%26+Telogen+Effluvium\">🔍 Search on Google</a></header><p><i>(The 3 Most Common </i><i><b>Non-Scarring</b></i><i> Alopecias in Daily Outpatient Practice!)</i></p><table class=\"t \"><tr><td><p><b>Feature</b></p></td><td><p><b>Alopecia Areata</b></p></td><td><p><b>Androgenetic Alopecia </b><i><b>(Pattern Hair Loss)</b></i></p></td><td><p><b>Telogen Effluvium </b><i><b>(Post-Stress Shedding)</b></i></p></td></tr><tr><td></td><td></td><td></td><td></td></tr><tr><td><p><b>Pathophysiology</b></p></td><td><p>Autoimmune <b>CD8+ T-cell attack</b> on hair bulb</p></td><td><p><b>DHT</b> (Dihydrotestosterone)-mediated progressive follicular miniaturization</p></td><td><p>Synchronized premature shift of hairs into resting (<b>Telogen</b>) phase <b>2–3 MONTHS AFTER a physiologic shock!</b></p></td></tr><tr><td><p><b>Triggers / Associations</b></p></td><td><p>Thyroid disease, Vitiligo, Atopy</p></td><td><p>Genetics + Androgens (<mark class=\"hl lab\"><b> check PCOS</b></mark> if female has hirsutism/acne!)</p></td><td><p><b>High fever (COVID-19/Typhoid), Childbirth (Postpartum!), Crash dieting, Major surgery, Severe stress, Iron/Zn/Thyroid deficiency!</b></p></td></tr><tr><td><p><b>Clinical Picture</b></p></td><td><p>Sudden well-circumscribed <b>completely smooth, round bald patch(es)</b> + <b>\"Exclamation Mark\" Hairs</b> at borders + <b>nail pitting</b>!</p></td><td><p><i>Men:</i> Receding bitemporal hairline &amp; vertex! <i>Women: </i><b>Diffuse central crown thinning (\"Christmas Tree\" part widening) with SPARED frontal hairline!</b></p></td><td><p><b>Sudden diffuse shedding</b> (&gt; 100– 300 hairs/day on pillow/shower; <b>Positive Hair Pull Test </b>everywhere) with NO discrete bald patches!</p></td></tr><tr><td><p><b>Treatment</b></p></td><td><p><i>Limited patches:</i> <b>Intralesional Triamcinolone Acetonide</b> injections q4– 6 wks (+ Topical potent steroids / Minoxidil). <i>Severe (Alopecia Totalis/Universalis):</i> <b>Oral JAK Inhibitors (Baricitinib / Ritlecitinib)</b>!</p></td><td><p><b>Topical Minoxidil 5%</b> (foam/solution daily — lifelong!) <b>PLUS Oral Finasteride 1 mg/day</b> in men (<i>teratogenic — avoid in fertile women!</i>); <mark class=\"hl rx\"><b>Spironolactone</b></mark> in women!</p></td><td><p><mark class=\"hl mech\"><b>Reassurance + Treat underlying trigger (correct Ferritin [goal &gt; 50–70!], TSH, Vit D, nutrition)</b></mark> -&gt; <b>Self-limited, regrows completely in 6–12 months!</b></p></td></tr></table><p><i>(Contrast with </i><i><b>Scarring [Cicatricial] Alopecia</b></i><i> — e.g., </i><i><b>Discoid Lupus, Lichen Planopilaris, Neglected Tinea Capitis Kerion</b></i><i>: shiny smooth scalp with </i><i><b>LOSS OF FOLLICULAR OSTIA</b></i><i> -&gt; permanent hair loss unless treated urgently!)</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u279\">← Case 17</button><button class=\"nv\" data-u=\"u281\">Case 19 →</button></nav></article><article class=\"view unit\" id=\"u281\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 19</span><h1>Erythema Nodosum &amp; Pyoderma Gangrenosum</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Erythema+Nodosum+%26+Pyoderma+Gangrenosum\">🔍 Search on Google</a></header><h3><b>A. Erythema Nodosum (#1 Panniculitis — Inflammation of Subcutaneous Fat!)</b></h3><ul>\n<li class=\"l1\"><b>Clinical Picture:</b> Sudden onset of <mark class=\"hl lab\"><b>bilateral, symmetrical, exquisitely TENDER, warm, erythematous deep nodules (1–5 cm)</b></mark> on the <b>ANTERIOR SHINS (pretibial region)</b>, healing like bruises without ulceration or scarring!</li>\n<li class=\"l1\"><b>Etiology (Separated — ALWAYS HUNT FOR THE UNDERLYING TRIGGER! Mnemonic: \"SNOOT\"):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Infections:</b> <b>GAS</b> (Group A <i>Streptococcus</i> pharyngitis — #1 in kids!), <b>Pulmonary Tuberculosis (TB — crucial in Egypt!)</b>, Deep fungal infections, <i>Yersinia</i>.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Inflammatory / Autoimmune:</b> <b>Sarcoidosis</b> (<b>Löfgren’s Syndrome</b>: Bilateral hilar adenopathy + Erythema Nodosum + Ankle arthritis!), <mark class=\"hl lab\"><b>IBD</b></mark> (Inflammatory Bowel Disease — Crohn’s &gt; UC), <b>Behçet’s Disease</b> (common in Egypt!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Drugs / Pregnancy:</b> <b>Sulfonamides</b>, <b>OCPs</b> (Oral Contraceptives), <mark class=\"hl lab\"><b>Pregnancy</b></mark> .</span></p>\n<ul>\n<li class=\"l1\"><b>Workup &amp; Treatment:</b> <mark class=\"hl mech\"><b>CXR</b></mark> (Chest X-Ray — TB/Sarcoidosis!), <b>ASOT</b> (Anti-Streptolysin O Titer) / Throat swab, Pregnancy test, stool/GI check -&gt; <mark class=\"hl rx\"><b>Treat underlying cause + Bed rest, Leg elevation, &amp; NSAIDs</b></mark> (Potassium iodide or short steroids if severe after ruling out TB!).</li>\n</ul><h3><b>B. Pyoderma Gangrenosum</b></h3><ul>\n<li class=\"l1\"><b>Clinical Picture:</b> Starts as a painful pustule/nodule (often at site of minor needle prick/trauma — <b>\"Pathergy\"</b>!) rapidly breaking down into a <b>rapidly enlarging, agonizingly painful necrotic ulcer with VIOLACEOUS (purple) UNDERMINED BORDERS</b>!</li>\n<li class=\"l1\"><b>Associations (&gt; 50% Systemic):</b> <mark class=\"hl lab\"><b>IBD (Ulcerative Colitis / Crohn’s — #1!)</b></mark> , <b>Rheumatoid Arthritis</b>, <b>Acute Myeloid Leukemia / Myelodysplasia</b>.</li>\n<li class=\"l1\"><b>CRITICAL RULE:</b> <mark class=\"hl lab\"><b>DO NOT SURGICALLY DEBRIDE Pyoderma Gangrenosum!</b></mark> (Trauma triggers <b>Pathergy</b> and makes the ulcer explode in size!) -&gt; <mark class=\"hl rx\"><b>Rule out infection/fungus first, then treat with High-Dose Systemic Corticosteroids / Cyclosporine / Infliximab</b></mark> !</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u280\">← Case 18</button><button class=\"nv\" data-u=\"u282\">Case 20 →</button></nav></article><article class=\"view unit\" id=\"u282\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 20</span><h1>Cutaneous Lupus Erythematosus &amp; Dermatomyositis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Cutaneous+Lupus+Erythematosus+%26+Dermatomyositis\">🔍 Search on Google</a></header><h3><b>A. Cutaneous Lupus (SLE vs. Discoid Lupus)</b></h3><ul>\n<li class=\"l1\"><b>Acute Cutaneous Lupus (Malar / \"Butterfly\" Rash):</b> Symmetric erythematous plaques over malar cheeks and nasal bridge (<b>SPARING the nasolabial folds!</b>), triggered by <b>sunlight (photosensitivity)</b>; heals <b>WITHOUT scarring</b>; strongly linked to systemic <mark class=\"hl lab\"><b>SLE</b></mark> (Systemic Lupus Erythematosus).</li>\n<li class=\"l1\"><b>Chronic Discoid Lupus Erythematosus (DLE):</b> Well-demarcated erythematous plaques with adherent scale and <b>follicular plugging (\"carpet-tack\" sign)</b> on <b>scalp, ears, and face</b>, healing with <b>CENTRAL ATROPHY, HYPOPIGMENTATION, AND PERMANENT SCARRING ALOPECIA</b>! (~5–10% develop systemic SLE).</li>\n<li class=\"l1\"><i>Treatment:</i> <b>Strict Broad-Spectrum Sunscreen</b>, Potent Topical/Intralesional Corticosteroids, <mark class=\"hl rx\"><b>Oral Hydroxychloroquine</b></mark> (first-line systemic — requires baseline &amp; regular ophthalmology retinal screening!).</li>\n</ul><h3><b>B. Dermatomyositis (Check for Underlying Malignancy in Adults!)</b></h3><ul>\n<li class=\"l1\"><b>Classic Cutaneous Signs (Pathognomonic!):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Heliotrope Rash:</b> Violaceous/purple periorbital erythema &amp; edema on upper eyelids.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Gottron’s Papules:</b> Violaceous flat-topped scaly papules over <b>dorsal knuckles (MCPs &amp; PIPs)</b>!</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>\"Shawl Sign\" &amp; \"V-Sign\":</b> Photosensitive violaceous erythema on upper back/shoulders and anterior chest.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Mechanic’s Hands:</b> Rough cracked hyperkeratotic lateral fingers (<b>Anti-Jo-1</b> -&gt; high risk of <b>Interstitial Lung Disease!</b>).</span></p>\n<ul>\n<li class=\"l1\"><b>Muscle &amp; Cancer Rule:</b> Symmetric <b>proximal muscle weakness</b> + markedly elevated <b>CK</b> (Creatine Kinase) + Anti-Mi-2/Jo-1 -&gt; <mark class=\"hl mech\"><b>In Adults &gt; 40–50 yrs, SCREEN FOR OCCULT MALIGNANCY</b></mark> (Ovarian, Lung, GI, Breast, Nasopharyngeal cancer)!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u281\">← Case 19</button><button class=\"nv\" data-u=\"u283\">Case 21 →</button></nav></article><article class=\"view unit\" id=\"u283\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 21</span><h1>Leukocytoclastic Vasculitis (APPROACH TO PALPABLE PURPURA)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Leukocytoclastic+Vasculitis+%28APPROACH+TO+PALPABLE+PURPURA%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Immune-complex-mediated <b>small-vessel (post-capillary venule) vasculitis</b> characterized histopathologically by <b>fibrinoid necrosis and neutrophilic nuclear debris (\"karyorrhexis\")</b>.</p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Idiopathic (~50%).</b></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Infections (~15–20%):</b> <b>GAS</b>, <b>HCV</b> (<b>Cryoglobulinemia</b> — <i>very important in Egypt!</i>), <b>HBV</b>, Endocarditis, HIV.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Medications (~15–20%):</b> <mark class=\"hl rx\"><b>Penicillins, Cephalosporins, Sulfonamides, NSAIDs, Thiazides, Allopurinol</b></mark> (7–10 days after exposure!).</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Systemic Autoimmune / Malignancy:</b> <mark class=\"hl lab\"><b>IgA Vasculitis (HSP</b></mark> [Henoch-Schönlein Purpura]), <mark class=\"hl lab\"><b>SLE</b></mark> , <mark class=\"hl lab\"><b>RA</b></mark> , <mark class=\"hl mech\"><b>ANCA-associated vasculitis (GPA/MPA/EGPA)</b></mark> , Lymphoma.</span></p><h3><b>3. Clinical Picture (CRITICAL BEDSIDE TEST: DIASCOPY!)</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>Non-Blanching PALPABLE PURPURA</b></mark> (raised purple spots that do <b>NOT blanch</b> when pressed with a glass slide!) distributed over <b>dependent areas (lower legs, ankles, buttocks)</b>. <i>(Note: Flat non-palpable petechiae = Thrombocytopenia; </i><mark class=\"hl mech\"><i><b>PALPABLE</b></i></mark><i> purpura = </i><i><b>Small-Vessel Vasculitis</b></i><i> until proven otherwise!)</i></li>\n</ul><h3><b>4. Mandatory Workup &amp; Treatment</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Skin Punch Biopsy (+ DIF if IgA/HSP suspected)</b></mark> + <b>Screen for Systemic Organ Involvement:</b> <mark class=\"hl mech\"><b>Urinalysis</b></mark> (check hematuria/RBC casts for <b>Glomerulonephritis!</b>), <mark class=\"hl mech\"><b>RFTs</b></mark> , <mark class=\"hl mech\"><b>CBC</b></mark> , <mark class=\"hl mech\"><b>ESR/CRP</b></mark> , <b>HCV/HBV</b>, <mark class=\"hl mech\"><b>ANA, ANCA, Complement (C3/C4), Cryoglobulins</b></mark> , Stool occult blood!</li>\n<li class=\"l1\"><b>Treatment:</b> <b>Stop offending drug / Treat infection (e.g., HCV)</b>; mild skin-only disease -&gt; leg elevation + NSAIDs/Colchicine; severe/ulcerating skin or <b>renal/GI/nerve involvement</b> -&gt; <mark class=\"hl rx\"><b>Systemic Corticosteroids</b></mark> (+/- Rituximab/Cyclophosphamide if ANCA vasculitis)!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u282\">← Case 20</button><button class=\"nv\" data-u=\"u284\">Case 22 →</button></nav></article><article class=\"view unit\" id=\"u284\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 22</span><h1>Drug Eruptions (MORBILLIFORM, FIXED DRUG ERUPTION &amp; DRESS SYNDROME)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Drug+Eruptions+%28MORBILLIFORM%2C+FIXED+DRUG+ERUPTION+%26+DRESS+SYNDROME%29\">🔍 Search on Google</a></header><h3><b>1. Morbilliform (Exanthematous) Drug Eruption (~95% of All Drug Rashes!)</b></h3><ul>\n<li class=\"l1\"><b>Onset:</b> Typically <b>7–14 days</b> after starting a new drug (e.g., <mark class=\"hl rx\"><b>Amoxicillin/Ampicillin, TMP-SMX, Allopurinol, Anticonvulsants</b></mark> ).</li>\n<li class=\"l1\"><b>Clinical:</b> Symmetric, pruritic, blanching bright-red macules and papules starting on trunk -&gt; spreading outward; <b>NO mucosal ulcers, NO blisters, NO facial edema, NO fever/organ failure</b>!</li>\n<li class=\"l1\"><b>Treatment:</b> <b>Stop culprit drug</b> + Topical steroids + Oral antihistamines (resolves in 1–2 weeks!).</li>\n</ul><h3><b>2. Fixed Drug Eruption (FDE)</b></h3><ul>\n<li class=\"l1\"><b>Classic Clue:</b> Well-demarcated round/oval dusky <b>violaceous-to-brown plaque(s)</b> that recur in the <mark class=\"hl mech\"><b>EXACT SAME ANATOMICAL SITE</b></mark> (often lips, genitalia, hands) within hours every time the drug is re-ingested (<mark class=\"hl rx\"><b> NSAIDs, TMP-SMX, Tetracyclines, Metronidazole, Fluoroquinolones</b></mark> )! Heals with marked hyperpigmentation.</li>\n</ul><h3><b>3. DRESS Syndrome (Drug Reaction with Eosinophilia and Systemic Symptoms — LIFE-THREATENING!)</b></h3><ul>\n<li class=\"l1\"><b>Culprits:</b> <b>Anticonvulsants</b> (<b>Carbamazepine, Phenytoin, Lamotrigine</b>), <mark class=\"hl rx\"><b>Allopurinol</b></mark> , <b>Sulfonamides</b>, <mark class=\"hl rx\"><b>Vancomycin</b></mark> , Minocycline.</li>\n<li class=\"l1\"><b>Delayed Onset:</b> <b>2 – 6 WEEKS</b> after starting the drug!</li>\n<li class=\"l1\"><b>Clinical Triad:</b> <b>(1) High Fever + Widespread Morbilliform Rash WITH Marked FACIAL EDEMA</b>, <b>(2) Hematologic Abnormalities (Marked Eosinophilia &amp; Atypical Lymphocytes)</b>, and <mark class=\"hl mech\"><b>(3) Internal Organ Injury (Hepatitis [elevated ALT/AST — #1 cause of death!], Acute Interstitial Nephritis, Myocarditis, Pneumonitis)</b></mark> + Lymphadenopathy!</li>\n<li class=\"l1\"><b>Treatment:</b> <b>IMMEDIATE STOP of culprit drug</b> + <mark class=\"hl rx\"><b>Admit + Systemic Corticosteroids (Prednisone 1 mg/kg/day)</b></mark> tapered <b>SLOWLY over 6–12 weeks</b> (rapid taper causes relapse!) + monitor LFTs/RFTs/Thyroid for months!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u283\">← Case 21</button><button class=\"nv\" data-u=\"u285\">Case 23 →</button></nav></article><article class=\"view unit\" id=\"u285\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 23</span><h1>Pityriasis Alba, Keratosis Pilaris &amp; Xerosis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pityriasis+Alba%2C+Keratosis+Pilaris+%26+Xerosis\">🔍 Search on Google</a></header><p class=\"muted\"><i>(Three extremely common, benign outpatient complaints in Egyptian pediatric and adult clinics — frequently misdiagnosed as fungal infections or vitamin deficiencies!)</i></p>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Pityriasis Alba:</b></span></p>\n<ul>\n<li class=\"l2\"><i>Patient:</i> Children/adolescents (often with atopic background, worsened by sun exposure making surrounding skin tan!).</li>\n<li class=\"l2\"><i>Presentation:</i> Ill-defined, <b>hypopigmented (pale) dry patches with fine subtle scale</b> on the <b>CHEEKS/FACE</b>! <i>(Parents often fear it is Vitiligo or \"worms/parasites\"!)</i></li>\n<li class=\"l2\"><i>Differentiation:</i> <b>NOT chalk-white</b> under Wood’s lamp (unlike Vitiligo) and <b>KOH-negative</b> (unlike Tinea versicolor!).</li>\n<li class=\"l2\"><i>Treatment:</i> <b>Reassurance + Thick Emollients + Daily Sunscreen</b> (+/- brief 1% Hydrocortisone if erythematous early) — resolves spontaneously with age!</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Keratosis Pilaris (\"Chicken Skin\"):</b></span></p>\n<ul>\n<li class=\"l2\"><i>Presentation:</i> Tiny, rough, folliculocentric keratotic papules on <b>outer upper arms, anterior thighs, and cheeks</b> (harmless variant associated with atopy).</li>\n<li class=\"l2\"><i>Treatment:</i> Gentle <b>Emollients containing Urea (10%), Lactic Acid, or Salicylic Acid</b> (avoid harsh scrubbing!).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Xerosis Cutis (Asteatotic Eczema):</b> Dry cracked \"crazy-paving\" itchy shins in elderly/winter -&gt; replace hot baths/harsh soaps with lukewarm showers + immediate Petrolatum/Ceramide ointments!</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u284\">← Case 22</button><button class=\"nv\" data-u=\"u286\">Case 24 →</button></nav></article><article class=\"view unit\" id=\"u286\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 24</span><h1>Hidradenitis Suppurativa (ACNE INVERSA)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Hidradenitis+Suppurativa+%28ACNE+INVERSA%29\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Pathophysiology</b></h3><p>Chronic, recurrent, debilitating inflammatory disease of <b>follicular occlusion</b> in apocrine-gland-bearing <b>intertriginous skin</b> (NOT a primary bacterial sweat-gland infection!). Strongly linked to <b>Obesity and Cigarette Smoking</b>.</p><h3><b>2. Clinical Picture (Hurley Stages I–III)</b></h3><ul>\n<li class=\"l1\">Recurrent, deeply painful <b>inflamed nodules, sterile abscesses, draining sinus tracts, and rope-like bridging scars</b> in <mark class=\"hl mech\"><b>AXILLAE, GROIN/INFERIOR BREAST FOLDS, AND PERINEUM/BUTTOCKS</b></mark> + classic <b>\"Double-Headed\" Comedones</b>!</li>\n</ul><h3><b>3. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Lifestyle (Crucial):</b> <b>Smoking cessation</b>, weight loss, loose cotton clothing, <b>Benzoyl Peroxide / Chlorhexidine wash</b> (do NOT squeeze lesions!).</li>\n<li class=\"l1\"><b>Medical:</b> Topical Clindamycin 1% (mild) -&gt; <mark class=\"hl rx\"><b>Oral Doxycycline</b></mark> or <mark class=\"hl rx\"><b>Clindamycin + Rifampin</b></mark> (10–12 weeks for moderate flares) -&gt; <b>Biologics (Adalimumab [Anti-TNF] or Secukinumab)</b> for moderate-to-severe refractory disease + <b>Intralesional Triamcinolone</b> for acutely painful nodules + <b>Surgical Wide Excision/Deroofing</b> of chronic scarred sinus tracts!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u285\">← Case 23</button><button class=\"nv\" data-u=\"u287\">Case 25 →</button></nav></article><article class=\"view unit\" id=\"u287\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 25</span><h1>Generalized Pruritus Without a Primary Rash (SYSTEMIC APPROACH!)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Generalized+Pruritus+Without+a+Primary+Rash+%28SYSTEMIC+APPROACH%21%29\">🔍 Search on Google</a></header><p><i>(When a patient scratches severely yet the skin shows ONLY secondary excoriations/scabs and NO primary rash — </i><i><b>ALWAYS HUNT FOR AN INTERNAL CAUSE!</b></i><i>)</i></p><h4><b>Separated Systemic Etiologies (Mnemonic: \"HITCHED\" / Organ Checklist)</b></h4><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Simple Skin Dryness (Xerosis):</b> #1 cause in elderly (rule out first!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Hepatobiliary Cholestasis:</b> <mark class=\"hl lab\"><b>PBC</b></mark> (Primary Biliary Cholangitis), Obstructive Jaundice, <b>Intrahepatic Cholestasis of Pregnancy</b> (severe itching of palms/soles in 3rd trimester -&gt; check <b>Serum Bile Acids</b>!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Renal Failure (Uremic Pruritus):</b> Chronic Kidney Disease / Dialysis.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Hematologic / Malignancy:</b> <b>Polycythemia Vera</b> (<b>Aquagenic Pruritus</b> — intense itching <b>AFTER A WARM SHOWER</b>!), <b>Hodgkin Lymphoma</b> (night sweats + weight loss + itching!), <b>Iron Deficiency Anemia</b>!</span></p>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><b>Endocrine:</b> <mark class=\"hl lab\"><b>Hypothyroidism / Hyperthyroidism</b></mark> , Diabetes Mellitus.</span></p>\n<p class=\"num\"><span class=\"n\">6.</span><span class=\"nt\"><b>Drugs &amp; Infestations:</b> Opioids (histamine release), early Scabies (subtle burrows).</span></p><h4><b>Mandatory Initial Lab Screen</b></h4><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>CBC with Differential</b></mark> , <b>Ferritin</b>, <mark class=\"hl mech\"><b>RFTs</b></mark> , <mark class=\"hl mech\"><b>LFTs (ALP/Bilirubin)</b></mark> , <mark class=\"hl mech\"><b>TSH</b></mark> , <mark class=\"hl mech\"><b>HbA1c/Glucose</b></mark> , <b>Chest X-Ray</b> (if B-symptoms/lymphoma suspected), <b>HIV / HCV</b> (if risk factors).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u286\">← Case 24</button><button class=\"nv\" data-u=\"u288\">Case 26 →</button></nav></article><article class=\"view unit\" id=\"u288\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 26</span><h1>Basal Cell Carcinoma (BCC)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Basal+Cell+Carcinoma+%28BCC%29\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Risk Factors</b></h3><p>Slow-growing, locally invasive malignant tumor of basal epidermal keratinocytes — <b>#1 Most Common Skin Cancer Worldwide!</b> <b>Metastasis is extremely rare (&lt; 0.1%)</b>, <i>but neglected lesions destroy underlying nose/eyelid/bone (\"Rodent Ulcer\")!</i></p>\n<ul>\n<li class=\"l1\"><b>Risk Factors:</b> Cumulative <b>UVB Sun Exposure</b>, fair skin, advancing age, radiation therapy, <b>Gorlin Syndrome</b> (<i>PTCH1</i> gene).</li>\n</ul><h3><b>2. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><b>Sun-Exposed Areas (&gt; 80% on Head &amp; Neck — especially Nose, Upper Lip [above vermilion], Eyelids!):</b></li>\n<li class=\"l1\"><b>Classic Nodular BCC:</b> <b>Pearly, translucent, pink/flesh-colored papule/nodule</b> with <b>ROLLED WAXY BORDERS</b>, <mark class=\"hl rx\"><b>ARBORIZING (branching) TELANGIECTASIAS</b></mark> , and <b>CENTRAL ULCERATION (\"Rodent Ulcer\")</b> that bleeds easily with minor trauma (\"a pimple that never heals!\")!</li>\n</ul><h3><b>3. Diagnosis &amp; Treatment</b></h3><ul>\n<li class=\"l1\"><b>Confirm:</b> <b>Shave or Punch Biopsy</b> (histology: <b>palisading basaloid tumor nests with stromal retraction clefting</b>).</li>\n<li class=\"l1\"><b>Treatment:</b></li>\n<li class=\"l2\"><b>Surgical Excision with Clear Margins (4 mm)</b> — Standard of care!</li>\n<li class=\"l2\"><b>Mohs Micrographic Surgery:</b> Gold standard for <b>high-risk facial sites (\"H-zone\": nose, eyelids, ears, lips)</b> or recurrent/morpheaform BCC (spares healthy tissue while checking 100% of margins!).</li>\n<li class=\"l2\"><i>Superficial low-risk trunk BCC:</i> Topical Imiquimod / 5-FU or Curettage &amp; Electrodessication.</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u287\">← Case 25</button><button class=\"nv\" data-u=\"u289\">Case 27 →</button></nav></article><article class=\"view unit\" id=\"u289\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 27</span><h1>Squamous Cell Carcinoma (SCC) &amp; Actinic Keratosis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Squamous+Cell+Carcinoma+%28SCC%29+%26+Actinic+Keratosis\">🔍 Search on Google</a></header><h3><b>1. Actinic Keratosis (Premalignant Precursor!)</b></h3><ul>\n<li class=\"l1\"><b>Presentation:</b> Rough, gritty <b>\"sandpaper-like\" small erythematous/crusty macules</b> on chronically sun-exposed bald scalp, forehead, dorsal hands (better felt than seen!).</li>\n<li class=\"l1\"><b>Treatment:</b> <b>Liquid Nitrogen Cryotherapy</b> (spot treatment) or <b>Topical 5-Fluorouracil (5-FU) / Imiquimod</b> (field therapy).</li>\n</ul><h3><b>2. Invasive Cutaneous Squamous Cell Carcinoma (SCC)</b></h3><ul>\n<li class=\"l1\"><b>Etiology (Separated):</b> <b>(1) Cumulative UV Radiation</b>, <b>(2) Chronic Non-Healing Wounds/Burns/Sinus Tracts (\"Marjolin’s Ulcer\" — high metastatic risk!)</b>, <b>(3) Immunosuppression (Organ Transplant Recipients — SCC &gt; BCC in transplant patients!)</b>, <b>(4) Arsenic/HPV</b>.</li>\n<li class=\"l1\"><b>Clinical Picture:</b> Rapidly growing, firm, <b>hyperkeratotic/crusted erythematous plaque, nodule, or ulcer with indurated raised margins</b> on <b>lower lip, ears, scalp, dorsal hands</b>! (<i>Contrast:</i> <b>Keratoacanthoma</b> = rapid volcano-shaped nodule with central keratin plug growing over weeks!).</li>\n<li class=\"l1\"><b>Diagnosis &amp; Treatment:</b> <b>Biopsy</b> (histology: <b>keratin pearls &amp; atypical squamous cells invading dermis</b>) -&gt; <b>Surgical Excision (4–6 mm margins) or Mohs Surgery </b>(palpate draining lymph nodes — higher metastatic risk than BCC!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u288\">← Case 26</button><button class=\"nv\" data-u=\"u290\">Case 28 →</button></nav></article><article class=\"view unit\" id=\"u290\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 28</span><h1>Malignant Melanoma (ABCDEs &amp; BRESLOW DEPTH)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Malignant+Melanoma+%28ABCDEs+%26+BRESLOW+DEPTH%29\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Risk Factors</b></h3><p>Malignant neoplasm of melanocytes — <b>#1 Cause of Death From Skin Cancer!</b></p>\n<ul>\n<li class=\"l1\"><b>Risk Factors:</b> <b>Intense intermittent blistering sunburns in childhood</b>, fair skin/red hair, tanning beds, <b>&gt; 50–100 nevi / dysplastic nevi</b>, personal/family history of melanoma (<i>CDKN2A/BRAF</i> mutations).</li>\n</ul><h3><b>2. Clinical Warning Signs (\"ABCDE\" &amp; \"Ugly Duckling\" Sign)</b></h3><ul>\n<li class=\"l1\"><b>A</b>symmetry (one half doesn’t match the other).</li>\n<li class=\"l1\"><b>B</b>order irregularity (scalloped, notched, poorly defined).</li>\n<li class=\"l1\"><b>C</b>olor variation (shades of black, brown, tan, red, white, blue).</li>\n<li class=\"l1\"><b>D</b>iameter <b>&gt; 6 mm</b> (pencil eraser — though early melanomas can be smaller!).</li>\n<li class=\"l1\"><b>E</b>volving (<b>MOST IMPORTANT!</b> Any mole changing in size, shape, color, or bleeding/itching!).</li>\n<li class=\"l1\"><b>\"Ugly Duckling\" Sign:</b> A pigmented lesion that looks noticeably different from all surrounding moles on the patient’s body!</li>\n</ul><h3><b>3. Major Subtypes</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Superficial Spreading Melanoma (~70% — #1 Overall):</b></mark> Trunk (men), legs (women).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Nodular Melanoma (~15% — Worst Prognosis!):</b></mark> Vertical growth from the start (lacks radial phase!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Lentigo Maligna Melanoma:</b></mark> Sun-damaged face/neck of elderly.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Acral Lentiginous Melanoma (#1 Subtype in Darker-Skinned Populations Including Egypt/Africa/Asia!):</b></mark> Occurs on <b>Palms, Soles, and Subungual Nail Beds (Hutchinson’s Sign = dark pigment extending onto proximal nailfold!)</b> — unrelated to sun exposure!</span></p><h3><b>4. Diagnosis, Prognosis &amp; Treatment</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl mech\"><b>GOLD STANDARD BIOPSY:</b></mark> <b>Full-Thickness EXCISIONAL Biopsy</b> with narrow 1–3 mm margin (<i>NEVER shave or freeze a suspected melanoma — ruins measurement of depth!</i>).</li>\n<li class=\"l1\"><b>SINGLE MOST IMPORTANT PROGNOSTIC FACTOR:</b> <b>Breslow Tumor Thickness (Depth of Invasion in mm)</b>!</li>\n<li class=\"l1\"><b>Treatment:</b> <b>Wide Local Excision</b> (margins 0.5–2 cm based on Breslow depth!) <b>PLUS Sentinel Lymph Node Biopsy (SLNB)</b> if depth <b>≥ 0.8–1.0 mm</b> (or ulcerated); <b>Immunotherapy (Pembrolizumab / Nivolumab + Ipilimumab)</b> or <b>BRAF/MEK Inhibitors (Dabrafenib + Trametinib)</b> if <i>BRAF V600E</i> positive for Stage III/IV!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u289\">← Case 27</button><button class=\"nv\" data-u=\"u291\">Case 29 →</button></nav></article><article class=\"view unit\" id=\"u291\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 29</span><h1>Benign Skin Tumors &amp; Keloids vs. Hypertrophic Scars</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Benign+Skin+Tumors+%26+Keloids+vs.+Hypertrophic+Scars\">🔍 Search on Google</a></header><h3><b>1. Common Benign Lesions (Must Distinguish From Melanoma/BCC!)</b></h3><ul>\n<li class=\"l1\"><b>Seborrheic Keratosis:</b> Elderly patients; well-demarcated brown/black <b>warty plaques with a classic \"STUCK-ON\" greasy appearance</b> and horn cysts -&gt; completely benign (reassurance or cryotherapy if irritated; <i>sudden explosive eruption of hundreds = </i><i><b>Leser-Trélat Sign</b></i><i> -&gt; screen for occult </i><i><b>Gastric/GI Adenocarcinoma</b></i><i>!</i>).</li>\n<li class=\"l1\"><b>Dermatofibroma:</b> Firm, small hyperpigmented nodule on <b>lower legs of young women</b> (after minor insect bite) showing <b>\"Dimple / Fitzpatrick Sign\"</b> (dimples inward when pinched!).</li>\n<li class=\"l1\"><b>Epidermoid Cyst:</b> Dome-shaped mobile subcutaneous nodule with a <b>central dark punctum</b> containing foul cheese-like keratin (treat with complete wall excision when uninflamed!).</li>\n<li class=\"l1\"><b>Lipoma:</b> Soft, doughy, lobulated, mobile painless subcutaneous fat tumor.</li>\n</ul><h3><b>2. Keloid vs. Hypertrophic Scar (</b><b>Keloids Are Very Common on Sternum/Deltoid/Earlobes in Darker Skin!</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Hypertrophic Scar:</b> Raised fibrous scar that <b>STAYS STRICTLY WITHIN the original wound boundaries</b> and often regresses over time.</li>\n<li class=\"l1\"><b>Keloid:</b> Thick, shiny, firm collagen overgrowth that <mark class=\"hl lab\"><b>EXTENDS BEYOND the original wound borders</b></mark> (claw-like projections), commonly on <b>earlobes (piercings), sternum, shoulders/upper back</b>, and recurs aggressively after simple surgical excision!</li>\n<li class=\"l1\"><b>Treatment of Keloids:</b> <b>Intralesional Triamcinolone Acetonide</b> injections q4–6 weeks + Silicone gel sheeting (+/- Cryotherapy; avoid surgery alone unless combined with post-op steroid injection/radiation!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u290\">← Case 28</button><button class=\"nv\" data-u=\"u292\">Case 30 →</button></nav></article><article class=\"view unit\" id=\"u292\" hidden style=\"--c:#a23fb5\"><button class=\"back\" data-p=\"11\">← Dermatology</button><header class=\"uh\"><span class=\"ul\">Case 30</span><h1>Cutaneous Markers of Internal Disease</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Cutaneous+Markers+of+Internal+Disease\">🔍 Search on Google</a></header><p class=\"muted\"><i>(A great physician reads the patient’s skin like an open textbook of internal medicine!)</i></p><table class=\"t \"><tr class=\"hd\"><th><p><b>Cutaneous Marker</b></p></th><th><p><b>Appearance &amp; Location</b></p></th><th><p><b>Associated Internal Disease</b></p></th></tr><tr><td><p><b>Acanthosis Nigricans</b></p></td><td><p>Velvety, hyperpigmented thickened plaques in <b>neck creases &amp; axillae</b></p></td><td><p><mark class=\"hl lab\"><b>Insulin Resistance / Obesity / T2DM / PCOS</b></mark> <i>(If </i><i><b>sudden, severe, elderly, involving palms/mouth</b></i><i> -&gt; </i><i><b>Gastric Adenocarcinoma</b></i><i>!)</i></p></td></tr><tr><td><p><b>Necrobiosis Lipoidica</b></p></td><td><p>Well-demarcated yellow-brown waxy atrophic plaques with telangiectasias on <b>anterior shins</b></p></td><td><p><b>Diabetes Mellitus</b> (T1DM &gt; T2DM)</p></td></tr><tr><td><p><b>Dermatitis Herpetiformis</b></p></td><td><p><b>Exquisitely pruritic grouped vesicles/excoriations</b> on <b>elbows, knees, buttocks, scalp</b></p></td><td><p><b>Celiac Disease</b> (IgA deposits at dermal papillae — responds to <b>Gluten-Free Diet + Dapsone</b>!)</p></td></tr><tr><td><p><b>Porphyria Cutanea Tarda (PCT)</b></p></td><td><p><b>Fragile blisters, erosions, milia, &amp; hypertrichosis on SUN-EXPOSED DORSAL HANDS!</b></p></td><td><p><b>Chronic Hepatitis C Virus (HCV — VERY RELEVANT IN EGYPT!)</b>, Iron overload, Alcohol!</p></td></tr><tr><td><p><b>Eruptive Xanthomas</b></p></td><td><p>Sudden crops of yellow-pink papules on buttocks/extensors</p></td><td><p><b>Severe Hypertriglyceridemia (&gt; 1,000 mg/dL)</b> -&gt; risk of Acute Pancreatitis!</p></td></tr><tr><td><p><b>Xanthelasma</b></p></td><td><p>Soft yellow plaques on medial eyelids</p></td><td><p>Hypercholesterolemia (<b>~50% have normal lipids!</b>)</p></td></tr><tr><td><p><b>Pyoderma Gangrenosum / Erythema Nodosum</b></p></td><td><p>Undermined purple leg ulcer / Tender red shin nodules</p></td><td><p><mark class=\"hl lab\"><b>IBD (UC / Crohn’s)</b></mark> , Leukemia, Sarcoidosis, TB, Behçet’s</p></td></tr></table><p class=\"muted\"><i>End of Part 11B — Dermatology (30 Cases Complete!)</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u291\">← Case 29</button></nav></article>"});
